    ["Desaturate the primary icon when you should wait before using the ability."] = "Desatura l'icona principale quando dovresti aspettare prima di usare l'abilità.",
    ["If enabled, small indicators for target-swapping, aura-cancellation, etc. may appear on your primary icon."] = "Se attivo, sull'icona principale possono comparire piccoli indicatori per il cambio bersaglio, l'annullamento di un'aura, ecc.",
    ["If enabled, these indicators will appear on queued icons as well as the primary icon, when appropriate."] = "Se attivo, questi indicatori compariranno, quando opportuno, anche sulle icone in coda oltre che sull'icona principale.",
    ["Appearance"] = "Aspetto",
    ["%s Appearance"] = "Aspetto di %s",
    ["Specify the width of indicator icons."] = "Imposta la larghezza delle icone degli indicatori.",
    ["Specify the height of indicator icons."] = "Imposta l'altezza delle icone degli indicatori.",
    ["Select the zoom percentage for indicator icon textures. (Roughly 30% will trim off the default Blizzard borders.)"] = "Scegli la percentuale di zoom per le texture delle icone degli indicatori. (Circa il 30% toglie i bordi predefiniti di Blizzard.)",
    ["Keep Aspect Ratio"] = "Mantieni le proporzioni",
    ["When enabled, indicator icons will maintain their original aspect ratio when resized."] = "Se attivo, le icone degli indicatori mantengono le loro proporzioni originali quando vengono ridimensionate.",
    ["Indicators"] = "Indicatori",
    ["Indicators are small icons that can indicate target-swapping or (rarely) cancelling auras."] = "Gli indicatori sono piccole icone che possono segnalare un cambio bersaglio o (raramente) l'annullamento di aure.",
    ["Call Action List"] = "Chiama lista di azioni",
    ["Cancel Action"] = "Annulla azione",
    ["Cancel Buff"] = "Annulla potenziamento",
    ["Healthstone"] = "Pietra della salute",
    ["Null Cooldown"] = "Cooldown nullo",
    ["Pool Resource"] = "Accumula risorsa",
    ["Potion"] = "Pozione",
    ["Run Action List"] = "Esegui lista di azioni",
    ["Trinket #1"] = "Ninnolo #1",
    ["Trinket #2"] = "Ninnolo #2",
    ["Use Items"] = "Usa oggetti",
    ["Variable"] = "Variabile",
    ["Wait"] = "Attendi",
    ["Monochrome"] = "Monocromatico",
    ["Monochrome, Outline"] = "Monocromatico, contorno",
    ["Monochrome, Thick Outline"] = "Monocromatico, contorno spesso",
    ["None"] = "Nessuno",
    ["Outline"] = "Contorno",
    ["Thick Outline"] = "Contorno spesso",
    ["Font"] = "Carattere",
    ["Style"] = "Stile",
    ["Color"] = "Colore",
    ["Top Left"] = "In alto a sinistra",
    ["Top Right"] = "In alto a destra",
    ["Bottom Left"] = "In basso a sinistra",
    ["Bottom Right"] = "In basso a destra",
    ["Left Top"] = "Sinistra in alto",
    ["Left Bottom"] = "Sinistra in basso",
    ["Right Top"] = "Destra in alto",
    ["Right Bottom"] = "Destra in basso",
    ["|cFF00FF00Checked|r"] = "|cFF00FF00Selezionato|r",
    ["|cFFFF0000Unchecked|r"] = "|cFFFF0000Non selezionato|r",
    ["Multiple"] = "Multiplo",
    ["Allows editing of multiple displays at once.  Settings displayed are from the Primary display (other display settings are shown in the tooltip).\n\nCertain options are disabled when editing multiple displays."] = "Permette di modificare più riquadri insieme.  Le impostazioni mostrate sono quelle del riquadro Principale (le impostazioni degli altri riquadri sono nel suggerimento).\n\nAlcune opzioni sono disattivate quando modifichi più riquadri.",
    ["|cFF00FF00Primary|r"] = "|cFF00FF00Principale|r",
    ["|cFFFF0000Primary|r"] = "|cFFFF0000Principale|r",
    ["Changes |cFF00FF00will|r be applied to the Primary display."] = "Le modifiche |cFF00FF00verranno|r applicate al riquadro Principale.",
    ["Changes |cFFFF0000will not|r be applied to the Primary display."] = "Le modifiche |cFFFF0000non verranno|r applicate al riquadro Principale.",
    ["|cFF00FF00AOE|r"] = "|cFF00FF00AOE|r",
    ["|cFFFF0000AOE|r"] = "|cFFFF0000AOE|r",
    ["Changes |cFF00FF00will|r be applied to the AOE display."] = "Le modifiche |cFF00FF00verranno|r applicate al riquadro AOE.",
    ["Changes |cFFFF0000will not|r be applied to the AOE display."] = "Le modifiche |cFFFF0000non verranno|r applicate al riquadro AOE.",
    [" |cFF00FF00Cooldowns|r"] = " |cFF00FF00Cooldown|r",
    [" |cFFFF0000Cooldowns|r"] = " |cFFFF0000Cooldown|r",
    ["Changes |cFF00FF00will|r be applied to the Cooldowns display."] = "Le modifiche |cFF00FF00verranno|r applicate al riquadro Cooldown.",
    ["Changes |cFFFF0000will not|r be applied to the Cooldowns display."] = "Le modifiche |cFFFF0000non verranno|r applicate al riquadro Cooldown.",
    [" |cFF00FF00Defensives|r"] = " |cFF00FF00Difese|r",
    [" |cFFFF0000Defensives|r"] = " |cFFFF0000Difese|r",
    ["Changes |cFF00FF00will|r be applied to the Defensives display."] = "Le modifiche |cFF00FF00verranno|r applicate al riquadro Difese.",
    ["Changes |cFFFF0000will not|r be applied to the Defensives display."] = "Le modifiche |cFFFF0000non verranno|r applicate al riquadro Difese.",
    [" |cFF00FF00Interrupts|r"] = " |cFF00FF00Interruzioni|r",
    [" |cFFFF0000Interrupts|r"] = " |cFFFF0000Interruzioni|r",
    ["Changes |cFF00FF00will|r be applied to the Interrupts display."] = "Le modifiche |cFF00FF00verranno|r applicate al riquadro Interruzioni.",
    ["Changes |cFFFF0000will not|r be applied to the Interrupts display."] = "Le modifiche |cFFFF0000non verranno|r applicate al riquadro Interruzioni.",
    ["Icons"] = "Icone",
    ["Includes display position, icon size/shape, etc."] = "Comprende posizione del riquadro, dimensione e forma delle icone, ecc.",
    ["If disabled, this display will not appear under any circumstances."] = "Se disattivato, questo riquadro non comparirà in nessun caso.",
    ["Select how this display draws its recommendations.  Each style has its own settings tabs."] = "Scegli come questo riquadro disegna le sue raccomandazioni.  Ogni stile ha le sue schede di impostazioni.",
    ["Apply ElvUI Cooldown Style to Primary Icon"] = "Applica lo stile cooldown di ElvUI all'icona principale",
    ["If ElvUI is installed, you can apply the ElvUI cooldown style to your queued icons.\n\nDisabling this setting requires you to reload your UI (|cFFFFD100/reload|r)."] = "Se ElvUI è installato, puoi applicare lo stile cooldown di ElvUI alle tue icone in coda.\n\nPer disattivare questa impostazione devi ricaricare l'interfaccia (|cFFFFD100/reload|r).",
    ["Icons Shown"] = "Icone mostrate",
    ["Specify the number of recommendations to show.  Each icon shows an additional step forward in time."] = "Imposta quante raccomandazioni mostrare.  Ogni icona mostra un passo in più avanti nel tempo.",
    ["Forecast Period"] = "Periodo di previsione",
    ["Specify the amount of time that the addon can look forward to generate a recommendation.  For example, in a Cooldowns display, if this is set to |cFFFFD10015|r (default), then a cooldown ability could start to appear when it has 15 seconds remaining on its cooldown and its usage conditions are met.\n\nIf set to a very short period of time, recommendations may be prevented due to having no abilities off cooldown with resource requirements and usage conditions met."] = "Imposta quanto tempo in avanti l'addon può guardare per generare una raccomandazione.  Per esempio, in un riquadro Cooldown, se è impostato su |cFFFFD10015|r (predefinito), un'abilità con cooldown può cominciare a comparire quando le restano 15 secondi di cooldown e le sue condizioni di utilizzo sono soddisfatte.\n\nSe lo imposti su un tempo molto breve, le raccomandazioni potrebbero essere bloccate perché nessuna abilità è fuori cooldown con i requisiti di risorse e le condizioni di utilizzo soddisfatti.",
    ["X"] = "X",
    ["Set the horizontal position for this display's primary icon relative to the center of the screen.  Negative values will move the display left; positive values will move it to the right."] = "Imposta la posizione orizzontale dell'icona principale di questo riquadro rispetto al centro dello schermo.  I valori negativi spostano il riquadro a sinistra; quelli positivi a destra.",
    ["Y"] = "Y",
    ["Set the vertical position for this display's primary icon relative to the center of the screen.  Negative values will move the display down; positive values will move it up."] = "Imposta la posizione verticale dell'icona principale di questo riquadro rispetto al centro dello schermo.  I valori negativi spostano il riquadro in basso; quelli positivi in alto.",
    ["Display Frame Layer"] = "Livello del riquadro",
    ["Strata"] = "Strato",
    ["Frame Strata determines which graphical layer that this display is drawn on.\n\nThe default layer is |cFFFFD100MEDIUM|r."] = "Lo strato del riquadro determina su quale livello grafico viene disegnato questo riquadro.\n\nIl livello predefinito è |cFFFFD100MEDIUM|r.",
    ["Modern"] = "Moderno",
    ["The game's own truth painted over this display's icons, whatever its style."] = "La verità del gioco stesso dipinta sopra le icone di questo riquadro, qualunque sia il suo stile.",
    ["Experimental. Keeps this display's style and settings, and adds the game's own cooldown swipes, an immediate grey when the game says an ability cannot be used yet, and a gold glow on the next ability when the game lights its proc. Hekili still decides what to show."] = "Sperimentale. Mantiene lo stile e le impostazioni di questo riquadro e aggiunge i cooldown veri del gioco, un grigio immediato quando il gioco dice che un'abilità non può ancora essere usata e un bagliore dorato sull'abilità successiva quando il gioco accende il suo proc. Hekili decide comunque cosa mostrare.",
    ["Modern (game truth)"] = "Moderno (verità del gioco)",
    ["Turn the Modern overlays on for this display. Turn it off to go back to the plain style."] = "Attiva le sovrapposizioni Moderno per questo riquadro. Disattivalo per tornare allo stile semplice.",
    ["Real Cooldown Swipes"] = "Cooldown reali",
    ["Show the game's own cooldown on an icon while it runs, instead of Hekili's estimate."] = "Mostra su un'icona il cooldown vero del gioco mentre è in corso, invece della stima di Hekili.",
    ["Grey When Not Usable"] = "Grigio se non utilizzabile",
    ["Grey an icon as soon as the game says the ability cannot be used yet (short of resource, or its proc or condition is not up)."] = "Rende grigia un'icona appena il gioco dice che l'abilità non può ancora essere usata (risorse insufficienti, oppure il suo proc o la sua condizione non sono attivi).",
    ["Proc Glow"] = "Bagliore del proc",
    ["Glow the next ability (and the focus ability) when the game lights its proc. An alternative to the display style's own proc glow: never shown on a greyed icon, and only on the next and focus icons. Turn the style's own glow off when you use this."] = "Fa brillare l'abilità successiva (e quella del focus) quando il gioco accende il suo proc. È un'alternativa al bagliore del proc dello stile del riquadro: non compare mai su un'icona grigia e solo sulle icone successiva e focus. Disattiva il bagliore dello stile quando usi questa opzione.",
    ["Visibility"] = "Visibilità",
    ["Visibility and transparency settings in PvE / PvP."] = "Impostazioni di visibilità e trasparenza in PvE / PvP.",
    ["Advanced"] = "Avanzate",
    ["If checked, options are provided to fine-tune display visibility and transparency."] = "Se selezionato, compaiono opzioni per regolare con precisione visibilità e trasparenza del riquadro.",
    ["PvE Alpha"] = "Opacità PvE",
    ["Set the transparency of the display when in PvE environments.  If set to 0, the display will not appear in PvE."] = "Imposta la trasparenza del riquadro negli ambienti PvE.  Se è 0, il riquadro non compare in PvE.",
    ["PvP Alpha"] = "Opacità PvP",
    ["Set the transparency of the display when in PvP environments.  If set to 0, the display will not appear in PvP."] = "Imposta la trasparenza del riquadro negli ambienti PvP.  Se è 0, il riquadro non compare in PvP.",
    ["PvE"] = "PvE",
    ["Default"] = "Predefinita",
    ["If non-zero, this display is shown with the specified level of opacity by default."] = "Se diverso da zero, questo riquadro è mostrato per impostazione predefinita con il livello di opacità indicato.",
    ["Combat"] = "Combattimento",
    ["If non-zero, this display is shown with the specified level of opacity in PvE combat."] = "Se diverso da zero, questo riquadro è mostrato con il livello di opacità indicato nel combattimento PvE.",
    ["Target"] = "Bersaglio",
    ["If non-zero, this display is shown with the specified level of opacity when you have an attackable PvE target."] = "Se diverso da zero, questo riquadro è mostrato con il livello di opacità indicato quando hai un bersaglio PvE attaccabile.",
    ["Combat w/ Target"] = "Combattimento con bersaglio",
    ["If non-zero, this display is shown with the specified level of opacity when you are in combat and have an attackable PvE target."] = "Se diverso da zero, questo riquadro è mostrato con il livello di opacità indicato quando sei in combattimento e hai un bersaglio PvE attaccabile.",
    ["Hide When Mounted"] = "Nascondi in sella",
    ["If checked, the display will not be visible when you are mounted when out of combat."] = "Se selezionato, il riquadro non sarà visibile quando sei in sella fuori dal combattimento.",
    ["PvP"] = "PvP",
    ["If non-zero, this display is shown with the specified level of opacity in PvP combat."] = "Se diverso da zero, questo riquadro è mostrato con il livello di opacità indicato nel combattimento PvP.",
    ["If non-zero, this display is shown with the specified level of opacity when you have an attackable PvP target."] = "Se diverso da zero, questo riquadro è mostrato con il livello di opacità indicato quando hai un bersaglio PvP attaccabile.",
    ["If non-zero, this display is shown with the specified level of opacity when you are in combat and have an attackable PvP target."] = "Se diverso da zero, questo riquadro è mostrato con il livello di opacità indicato quando sei in combattimento e hai un bersaglio PvP attaccabile.",
    ["If checked, the display will not be visible when you are mounted unless you are in combat."] = "Se selezionato, il riquadro non sarà visibile quando sei in sella, a meno che tu non sia in combattimento.",
    ["Displays"] = "Riquadri",
    ["Hekili Forever has up to five built-in displays (identified in blue) that can display different kinds of recommendations.  The addon's recommendations are based upon the Priorities that are generally (but not exclusively) based on SimulationCraft profiles so that you can compare your performance to the results of your simulations."] = "Hekili Forever ha fino a cinque riquadri integrati (indicati in blu) che possono mostrare diversi tipi di raccomandazioni.  Le raccomandazioni dell'addon si basano sulle Priorità, che in genere (ma non solo) derivano dai profili di SimulationCraft, così puoi confrontare le tue prestazioni con i risultati delle tue simulazioni.",
    ["Notification Panel"] = "Pannello notifiche",
    ["The Notification Panel provides brief updates when settings are changed or toggled while in combat."] = "Il Pannello notifiche dà brevi aggiornamenti quando le impostazioni vengono cambiate o alternate durante il combattimento.",
    ["|cFF1EFF00Notification Panel|r"] = "|cFF1EFF00Pannello notifiche|r",
    ["Enter the horizontal position of the notification panel, relative to the center of the screen.  Negative values move the panel left; positive values move the panel right."] = "Inserisci la posizione orizzontale del pannello notifiche rispetto al centro dello schermo.  I valori negativi spostano il pannello a sinistra; quelli positivi a destra.",
    ["Enter the vertical position of the notification panel, relative to the center of the screen.  Negative values move the panel down; positive values move the panel up."] = "Inserisci la posizione verticale del pannello notifiche rispetto al centro dello schermo.  I valori negativi spostano il pannello in basso; quelli positivi in alto.",
    ["Fonts"] = "Caratteri",
    ["Changing the font below will modify |cFFFF0000ALL|r text on all displays.\nTo modify one bit of text individually, select the Display (at left) and select the appropriate text."] = "Cambiando il carattere qui sotto modificherai |cFFFF0000TUTTI|r i testi di tutti i riquadri.\nPer modificare un singolo testo, scegli il Riquadro (a sinistra) e poi il testo che ti interessa.",
    ["Action Bar Glow"] = "Bagliore sulla barra azioni",
    ["Preferences for the glow around your action bar buttons."] = "Preferenze per il bagliore intorno ai pulsanti della tua barra azioni.",
    ["|cFF1EFF00Action Bar Glow|r"] = "|cFF1EFF00Bagliore sulla barra azioni|r",
    ["Glows the real buttons on your action bars that cast the first recommendation of a display, and the second recommendation's in another color. It works with the display itself hidden."] = "Fa brillare i pulsanti veri delle tue barre azioni che lanciano la prima raccomandazione di un riquadro, e quelli della seconda raccomandazione con un altro colore. Funziona anche con il riquadro nascosto.",
    ["If enabled, the action buttons that cast the followed display's first recommendation glow."] = "Se attivo, brillano i pulsanti azione che lanciano la prima raccomandazione del riquadro seguito.",
    ["Follow Display"] = "Segui riquadro",
    ["The display whose recommendations the glow follows."] = "Il riquadro di cui il bagliore segue le raccomandazioni.",
    ["In Combat Only"] = "Solo in combattimento",
    ["If enabled, the buttons glow only while you are in combat."] = "Se attivo, i pulsanti brillano solo mentre sei in combattimento.",
    ["Now Color"] = "Colore \"ora\"",
    ["The glow on the buttons of the first recommendation."] = "Il bagliore sui pulsanti della prima raccomandazione.",
    ["Glow the next recommendation"] = "Fai brillare la raccomandazione successiva",
    ["If enabled, the buttons of the second recommendation glow too, in the next color."] = "Se attivo, brillano anche i pulsanti della seconda raccomandazione, con il colore \"prossima\".",
    ["Next Color"] = "Colore \"prossima\"",
    ["The glow on the buttons of the second recommendation."] = "Il bagliore sui pulsanti della seconda raccomandazione.",
    ["Sharing"] = "Condivisione",
    ["Share Styles"] = "Condividi gli stili",
    ["Your display styles can be shared with other addon users with these export strings.\n\nYou can also import a shared export string here."] = "Puoi condividere gli stili dei tuoi riquadri con altri utenti dell'addon con queste stringhe di esportazione.\n\nQui puoi anche importare una stringa di esportazione condivisa.",
    ["|cFF1EFF00Share Styles|r"] = "|cFF1EFF00Condividi gli stili|r",
    ["Your display options can be shared with other addon users with these export strings.\n\nYou can also import a shared export string here."] = "Puoi condividere le opzioni dei tuoi riquadri con altri utenti dell'addon con queste stringhe di esportazione.\n\nQui puoi anche importare una stringa di esportazione condivisa.",
    ["Import"] = "Importa",
    ["Select a saved Style or paste an import string in the box provided."] = "Scegli uno Stile salvato oppure incolla una stringa di importazione nella casella.",
    ["Import String"] = "Stringa di importazione",
    ["Select a Saved Style"] = "Scegli uno Stile salvato",
    ["Import Style"] = "Importa stile",
    ["The Import String provided could not be decompressed.\n"] = "Non è stato possibile decomprimere la stringa di importazione fornita.\n",
    ["The imported style will create the following display(s):  "] = "Lo stile importato creerà questi riquadri:  ",
    ["The imported style will overwrite the following display(s):  "] = "Lo stile importato sovrascriverà questi riquadri:  ",
    ["Apply Changes"] = "Applica le modifiche",
    ["Reset"] = "Reimposta",
    ["Imported settings were successfully applied!\n\nClick Reset to start over, if needed."] = "Le impostazioni importate sono state applicate!\n\nSe serve, clicca Reimposta per ricominciare.",
    ["Export"] = "Esporta",
    ["Select the display style settings to export, then click Export Styles to generate an export string."] = "Scegli le impostazioni di stile dei riquadri da esportare, poi clicca Esporta stili per generare una stringa di esportazione.",
    ["Export Style"] = "Esporta stile",
    ["Style String"] = "Stringa dello stile",
    ["You can copy the above string to share your selected display style settings, or use the options below to store these settings (to be retrieved at a later date)."] = "Puoi copiare la stringa qui sopra per condividere le impostazioni di stile scelte, oppure usare le opzioni qui sotto per conservarle (e recuperarle più avanti).",
    ["Save Style"] = "Salva stile",
    ["Style Name"] = "Nome dello stile",
    ["Store Export String"] = "Conserva la stringa di esportazione",
    ["By storing your export string, you can save these display settings and retrieve them later if you make changes to your settings.\n\nThe stored style can be retrieved from any of your characters, even if you are using different profiles."] = "Conservando la tua stringa di esportazione puoi salvare queste impostazioni dei riquadri e recuperarle più tardi se cambi le tue impostazioni.\n\nLo stile conservato può essere recuperato da qualsiasi tuo personaggio, anche se usi profili diversi.",
    ["There is already a style with the name '%s' -- overwrite it?"] = "Esiste già uno stile con il nome '%s' -- sovrascriverlo?",
    ["Restart"] = "Ricomincia",
    ["Paste your SimulationCraft action priority list or profile here."] = "Incolla qui la tua lista di priorità di azioni o il tuo profilo SimulationCraft.",
    ["The import for '%s' required some automated changes."] = "L'importazione di '%s' ha richiesto alcune modifiche automatiche.",
    ["This profile is missing support for generic trinkets.  It is recommended that every priority includes either:\n - [Use Items], which includes any trinkets not explicitly included in the priority; or\n - [Trinket 1] and [Trinket 2], which will recommend the trinket for the numbered slot."] = "In questo profilo manca il supporto per i ninnoli generici.  Si consiglia che ogni priorità includa:\n - [Usa oggetti], che comprende tutti i ninnoli non inclusi esplicitamente nella priorità; oppure\n - [Ninnolo 1] e [Ninnolo 2], che consiglieranno il ninnolo dello slot numerato.",
    ["No action lists were imported from this profile."] = "Da questo profilo non è stata importata nessuna lista di azioni.",
    ["Imported %s action lists."] = "Importate %s liste di azioni.",
    ["Disable %s"] = "Disattiva %s",
    ["If checked, this ability will |cffff0000NEVER|r be recommended by the addon.  This can cause issues for some specializations, if other abilities depend on you using |W%s|w."] = "Se selezionato, questa abilità non verrà |cffff0000MAI|r consigliata dall'addon.  Questo può causare problemi ad alcune specializzazioni, se altre abilità dipendono dal fatto che tu usi |W%s|w.",
    ["Boss Encounter Only"] = "Solo negli scontri con i boss",
    ["If checked, the addon will not recommend |W%s|w unless you are in a boss fight (or encounter).  If left unchecked, |W%s|w can be recommended in any type of fight."] = "Se selezionato, l'addon non consiglierà |W%s|w a meno che tu non sia in uno scontro con un boss (o incontro).  Se non è selezionato, |W%s|w può essere consigliato in qualsiasi tipo di scontro.",
    ["Override Keybind Text"] = "Sostituisci il testo della scorciatoia",
    ["If specified, the addon will show this text in place of the auto-detected keybind text when recommending this ability.  This can be helpful if your keybinds are detected incorrectly or is found on multiple action bars."] = "Se compilato, l'addon mostrerà questo testo al posto della scorciatoia rilevata automaticamente quando consiglia questa abilità.  Può servire se le tue scorciatoie vengono rilevate male o si trovano su più barre azioni.",
    ["%s\n|cFFFFD100%s|r detected on action page |cFFFFD100%d."] = "%s\n|cFFFFD100%s|r rilevato nella pagina azioni |cFFFFD100%d.",
    ["\n|cFFFFD100No keybind detected for this ability.|r"] = "\n|cFFFFD100Nessuna scorciatoia rilevata per questa abilità.|r",
    ["Keybindings should be no longer than 20 characters in length."] = "Le scorciatoie non devono superare i 20 caratteri.",
    ["Require Toggle"] = "Richiede interruttore",
    ["Specify a required toggle for this action to be used in the addon action list.  When toggled off, abilities are treated as unusable and the addon will pretend they are on cooldown (unless specified otherwise)."] = "Indica un interruttore richiesto perché questa azione venga usata nella lista di azioni dell'addon.  Quando l'interruttore è spento, le abilità sono considerate inutilizzabili e l'addon farà finta che siano in cooldown (salvo diversa indicazione).",
    ["Minor CDs"] = "Cooldown minori",
    ["Default |cffffd100(%s)|r"] = "Predefinito |cffffd100(%s)|r",
    ["Potions"] = "Pozioni",
    ["Custom 1"] = "Personalizzato 1",
    ["Custom 2"] = "Personalizzato 2",
    ["Minimum Targets"] = "Bersagli minimi",
    ["If set above zero, the addon will only allow %s to be recommended, if there are at least this many detected enemies.  All other action list conditions must also be met.\nSet to zero to ignore."] = "Se è maggiore di zero, l'addon consiglierà %s solo se sono stati rilevati almeno questi nemici.  Devono essere soddisfatte anche tutte le altre condizioni della lista di azioni.\nImposta a zero per ignorare.",
    ["Maximum Targets"] = "Bersagli massimi",
    ["If set above zero, the addon will only allow %s to be recommended if there are this many detected enemies (or fewer).  All other action list conditions must also be met.\nSet to zero to ignore."] = "Se è maggiore di zero, l'addon consiglierà %s solo se sono stati rilevati questi nemici (o meno).  Devono essere soddisfatte anche tutte le altre condizioni della lista di azioni.\nImposta a zero per ignorare.",
    ["Maximum Applications"] = "Applicazioni massime",
    ["If set above zero, this ability will not be recommended when it has been applied to this number of targets (or more). If the aura is refreshable on your current target, this limit is ignored.\n\nSet to zero to ignore this limit."] = "Se è maggiore di zero, questa abilità non verrà consigliata quando è stata applicata a questo numero di bersagli (o più). Se l'aura può essere rinnovata sul tuo bersaglio attuale, questo limite viene ignorato.\n\nImposta a zero per ignorare questo limite.",
    ["Clash"] = "Anticipo",
    ["If set above zero, the addon will pretend %s has come off cooldown this much sooner than it actually has.  This can be helpful when an ability is very high priority and you want the addon to prefer it over abilities that are available sooner."] = "Se è maggiore di zero, l'addon farà finta che %s sia uscito dal cooldown con questo anticipo rispetto a quando succede davvero.  Può servire quando un'abilità ha una priorità molto alta e vuoi che l'addon la preferisca alle abilità disponibili prima.",
    ["If checked, this ability will |cffff0000NEVER|r be recommended by the addon.  This can cause issues for some specializations, if other abilities depend on you using %s."] = "Se selezionato, questa abilità non verrà |cffff0000MAI|r consigliata dall'addon.  Questo può causare problemi ad alcune specializzazioni, se altre abilità dipendono dal fatto che tu usi %s.",
    ["If checked, the addon will not recommend %s unless you are in a boss fight (or encounter).  If left unchecked, %s can be recommended in any type of fight."] = "Se selezionato, l'addon non consiglierà %s a meno che tu non sia in uno scontro con un boss (o incontro).  Se non è selezionato, %s può essere consigliato in qualsiasi tipo di scontro.",
    ["|cFFFFD100(GLOBAL)|r When Cooldowns Shown Separately, Use Actual Cooldown"] = "|cFFFFD100(GLOBALE)|r Quando i Cooldown sono mostrati separatamente, usa il cooldown reale",
    ["If checked |cFFFFD100and|r Cooldowns are Shown Separately |cFFFFD100and|r Cooldowns are enabled, the addon will |cFFFF0000NOT|r pretend your cooldown abilities are fully on cooldown.\n\nThis may help resolve scenarios where abilities become desynchronized due to behavior differences between the Cooldowns display and your other displays.\n\nSee |cFFFFD100Toggles|r > |cFFFFD100Cooldowns|r for the |cFFFFD100Cooldown: Show Separately|r feature."] = "Se selezionato |cFFFFD100e|r i Cooldown sono mostrati separatamente |cFFFFD100e|r i Cooldown sono attivi, l'addon |cFFFF0000NON|r farà finta che le tue abilità con cooldown siano completamente in cooldown.\n\nPuò aiutare a risolvere i casi in cui le abilità si desincronizzano a causa di differenze di comportamento tra il riquadro Cooldown e gli altri riquadri.\n\nVedi |cFFFFD100Interruttori|r > |cFFFFD100Cooldown|r per la funzione |cFFFFD100Cooldown: mostra separatamente|r.",
    ["%s\n|cFFFFD100No keybind detected for this ability.|r"] = "%s\n|cFFFFD100Nessuna scorciatoia rilevata per questa abilità.|r",
    ["Keybindings should be no longer than 6 characters in length."] = "Le scorciatoie non devono superare i 6 caratteri.",
    ["Icon Replacement"] = "Sostituzione dell'icona",
    ["If specified, the addon will attempt to load this texture instead of the default icon.  This can be a texture ID or a path to a texture file.\n\nLeave blank and press Enter to reset to the default icon."] = "Se compilato, l'addon cercherà di caricare questa texture al posto dell'icona predefinita.  Può essere l'ID di una texture o il percorso di un file di texture.\n\nLascia vuoto e premi Invio per tornare all'icona predefinita.",
    ["If checked, the addon will not recommend %s via [Use Items] unless you are in a boss fight (or encounter).  If left unchecked, %s can be recommended in any type of fight."] = "Se selezionato, l'addon non consiglierà %s tramite [Usa oggetti] a meno che tu non sia in uno scontro con un boss (o incontro).  Se non è selezionato, %s può essere consigliato in qualsiasi tipo di scontro.",
    ["If specified, the addon will show this text in place of the auto-detected keybind text when recommending this ability.  This can be helpful if the addon incorrectly detects your keybindings."] = "Se compilato, l'addon mostrerà questo testo al posto della scorciatoia rilevata automaticamente quando consiglia questa abilità.  Può servire se l'addon rileva male le tue scorciatoie.",
    ["Default |cffffd100(none)|r"] = "Predefinito |cffffd100(nessuno)|r",
    ["If set above zero, the addon will only allow %s to be recommended via [Use Items] if there are at least this many detected enemies.\nSet to zero to ignore."] = "Se è maggiore di zero, l'addon consiglierà %s tramite [Usa oggetti] solo se sono stati rilevati almeno questi nemici.\nImposta a zero per ignorare.",
    ["If set above zero, the addon will only allow %s to be recommended via [Use Items] if there are this many detected enemies (or fewer).\nSet to zero to ignore."] = "Se è maggiore di zero, l'addon consiglierà %s tramite [Usa oggetti] solo se sono stati rilevati questi nemici (o meno).\nImposta a zero per ignorare.",
    ["The Cooldown Manager is not available: %s"] = "Il Gestore dei cooldown non è disponibile: %s",
    ["The Cooldown Manager is not available."] = "Il Gestore dei cooldown non è disponibile.",
    ["Turn on the Cooldown Manager in the game options: it tells Hekili when your buffs and debuffs are up."] = "Attiva il Gestore dei cooldown nelle opzioni del gioco: dice a Hekili quando i tuoi potenziamenti e penalità sono attivi.",
    ["Activate %s"] = "Attiva %s",
    ["Recommend for %s from now on. The choice is kept for your current talent tree: a talent swap to another tree activates the specialization chosen for that one (also |cFFFFD100/hekili spec name|r)."] = "Da ora in poi consiglia per %s. La scelta viene mantenuta per il tuo albero di talenti attuale: se cambi talenti passando a un altro albero, si attiva la specializzazione scelta per quello (anche con |cFFFFD100/hekili spec nome|r).",
    ["|cFFFFD100Active|r"] = "|cFFFFD100Attiva|r",
    ["Specialization Settings"] = "Impostazioni di specializzazione",
    ["Core features and specialization options for %s."] = "Funzioni principali e opzioni di specializzazione per %s.",
    ["No recommendations while this specialization is active."] = "Nessuna raccomandazione finché questa specializzazione è attiva.",
    ["Priority"] = "Priorità",
    ["The addon will use the selected package when making its priority recommendations."] = "L'addon userà il pacchetto selezionato per fare le sue raccomandazioni di priorità.",
    ["(none)"] = "(nessuna)",
    ["Open and view this priority pack and its action lists."] = "Apri e guarda questo pacchetto di priorità e le sue liste di azioni.",
    ["Unless otherwise specified in the priority, the selected potion will be recommended."] = "Se la priorità non dice altrimenti, verrà consigliata la pozione selezionata.",
    ["Targeting"] = "Bersagli",
    ["Settings related to how enemies are identified and counted."] = "Impostazioni su come vengono identificati e contati i nemici.",
    ["These settings control how targets are counted when generating ability recommendations.\n\nBy default, the number of targets is shown on the bottom-right of the primary icon in the Primary and AOE displays, unless only one target is detected.\n\nYour true in-game target is always counted. \n\n|cFFFF0000WARNING:|r 'Soft' targets from the Action Targeting system are not presently supported.\n\n"] = "Queste impostazioni controllano come vengono contati i bersagli quando si generano le raccomandazioni delle abilità.\n\nPer impostazione predefinita, il numero di bersagli è mostrato in basso a destra dell'icona principale nei riquadri Principale e AOE, a meno che non venga rilevato un solo bersaglio.\n\nIl tuo vero bersaglio nel gioco viene sempre contato. \n\n|cFFFF0000ATTENZIONE:|r i bersagli 'morbidi' del sistema di Selezione bersaglio delle azioni al momento non sono supportati.\n\n",
    ["Your Target"] = "Il tuo bersaglio",
    ["Your actual target is always counted as an enemy, even if you do not have a target.\n\nThis setting cannot be disabled."] = "Il tuo bersaglio reale è sempre contato come nemico, anche se non hai un bersaglio.\n\nQuesta impostazione non si può disattivare.",
    ["Count Damaged Enemies"] = "Conta i nemici danneggiati",
    ["If checked, targets you've damaged will be counted as a valid enemy for several seconds, distinguishing them from other enemies that you have not attacked.\n\n%s Auto-enabled when nameplates are disabled\n\n%s Recommended for |cffffd100ranged|r unable to use |cffffd100Pet-Based Target Detection|r"] = "Se selezionato, i bersagli che hai danneggiato vengono contati come nemici validi per alcuni secondi, distinguendoli dagli altri nemici che non hai attaccato.\n\n%s Attivato automaticamente quando le barre dei nemici sono disattivate\n\n%s Consigliato per le specializzazioni |cffffd100a distanza|r che non possono usare il |cffffd100Rilevamento bersagli tramite il pet|r",
    ["Damage Detection"] = "Rilevamento dei danni",
    ["Include Enemies Damaged by Your Pets and Minions"] = "Includi i nemici danneggiati dai tuoi pet e servitori",
    ["If checked, the addon will count enemies that your pets or minions have hit (or hit you) within the past several seconds.  This may give misleading target counts if your pet/minions are spread out over the battlefield."] = "Se selezionato, l'addon conterà i nemici colpiti dai tuoi pet o servitori (o che hanno colpito te) negli ultimi secondi.  Può dare conteggi dei bersagli fuorvianti se i tuoi pet/servitori sono sparsi per il campo di battaglia.",
    ["Timeout"] = "Scadenza",
    ["Enemies will be counted until they have been ignored/undamaged for this period of time (or they die).\n\nIdeally, this period should reflect enough time that to continue to do AOE/cleave damage to enemies in this period, but not so long that enemies could have wandered out of range."] = "I nemici verranno contati finché non sono stati ignorati/non danneggiati per questo periodo di tempo (o finché non muoiono).\n\nIdealmente questo periodo dovrebbe essere abbastanza lungo da continuare a fare danni ad area/a più bersagli ai nemici in quel periodo, ma non così lungo che i nemici possano essersi allontanati fuori portata.",
    ["Include Enemies With Your DOTs / Debuffs"] = "Includi i nemici con i tuoi DOT / penalità",
    ["When checked, enemies that have your debuffs or damage-over-time effects will be counted as targets, regardless of their location on the battlefield.\n\nThis may not be ideal for melee specializations, as enemies may wander away after you've applied your dots/bleeds.  If |cFFFFD100Count Nameplates|r is enabled, enemies that are no longer in range will be filtered.\n\nRecommended for ranged specializations that will DoT multiple enemies and do not rely on the enemy being stacked for AOE damage."] = "Se selezionato, i nemici che hanno le tue penalità o effetti di danno nel tempo verranno contati come bersagli, indipendentemente dalla loro posizione sul campo di battaglia.\n\nPotrebbe non essere l'ideale per le specializzazioni di mischia, perché i nemici possono allontanarsi dopo che hai applicato i tuoi DOT/sanguinamenti.  Se |cFFFFD100Conta le barre dei nemici|r è attivo, i nemici che non sono più a portata verranno filtrati.\n\nConsigliato per le specializzazioni a distanza che applicano DOT a più nemici e non dipendono dal fatto che i nemici siano ammassati per il danno ad area.",
    ["Filter Off-Screen (Nameplate-less) Enemies"] = "Filtra i nemici fuori schermo (senza barra)",
    ["If checked, the damage-based target system will only count enemies that are on screen.  If unchecked, offscreen targets can be included in target counts.\n\n"] = "Se selezionato, il sistema di bersagli basato sul danno conterà solo i nemici sullo schermo.  Se non selezionato, i bersagli fuori schermo possono essere inclusi nel conteggio.\n\n",
    ["|cFFFF0000Requires Enemy Nameplates|r"] = "|cFFFF0000Richiede le barre dei nemici|r",
    ["|cFF00FF00Requires Enemy Nameplates|r"] = "|cFF00FF00Richiede le barre dei nemici|r",
    ["Count Nameplates Near You"] = "Conta le barre dei nemici vicine a te",
    ["If checked, enemy nameplates within the specified radius of your character will be counted as enemy targets.\n\n%s Recommended for melee specializations using a range of 10 yds or fewer\n\n%s Ranged specializations count enemies in combat out to the radius; target swaps need it."] = "Se selezionato, le barre dei nemici entro il raggio indicato dal tuo personaggio verranno contate come bersagli nemici.\n\n%s Consigliato per le specializzazioni di mischia con un raggio di 10 metri o meno\n\n%s Le specializzazioni a distanza contano i nemici in combattimento fino al raggio; i cambi bersaglio ne hanno bisogno.",
    ["Count Targets Near Your Pet"] = "Conta i bersagli vicini al tuo pet",
    ["If checked and properly configured, the addon will count targets near your pet as valid targets, when your target is also within range of your pet."] = "Se selezionato e configurato bene, l'addon conterà come bersagli validi quelli vicini al tuo pet, quando anche il tuo bersaglio è a portata del pet.",
    ["%s|w|r is on your action bar and will be used for all your %s pets."] = "%s|w|r è sulla tua barra azioni e verrà usato per tutti i tuoi pet %s.",
    ["\n\n|cFFFF0000Requires pet ability on one of your action bars.|r"] = "\n\n|cFFFF0000Richiede un'abilità del pet su una delle tue barre azioni.|r",
    ["\n\nEnemy nameplates are |cFF00FF00enabled|r and will be used to detect targets near your pet."] = "\n\nLe barre dei nemici sono |cFF00FF00attivate|r e verranno usate per rilevare i bersagli vicini al tuo pet.",
    ["\n\n|cFFFF0000Requires enemy nameplates.|r"] = "\n\n|cFFFF0000Richiede le barre dei nemici.|r",
    ["For pet-based detection to work, you must take an ability from your |cFF00FF00pet's spellbook|r and place it on one of |cFF00FF00your|r action bars.\n\n"] = "Perché il rilevamento tramite il pet funzioni, devi prendere un'abilità dal |cFF00FF00libro degli incantesimi del pet|r e metterla su una delle |cFF00FF00tue|r barre azioni.\n\n",
    ["For %s, %s is recommended due to its range.  It will work for all your pets."] = "Per %s si consiglia %s per via della sua portata.  Funzionerà con tutti i tuoi pet.",
    ["\nAlternative(s): "] = "\nAlternativa/e: ",
    ["and %s."] = "e %s.",
    ["|cFFFF0000WARNING!|r  Pet-based target detection requires |cFFFFD100enemy nameplates|r to be enabled."] = "|cFFFF0000ATTENZIONE!|r  Il rilevamento dei bersagli tramite il pet richiede che le |cFFFFD100barre dei nemici|r siano attivate.",
    ["\n\n|cFFFF0000WARNING!|r  Pet-based target detection requires |cFFFFD100enemy nameplates|r to be enabled."] = "\n\n|cFFFF0000ATTENZIONE!|r  Il rilevamento dei bersagli tramite il pet richiede che le |cFFFFD100barre dei nemici|r siano attivate.",
    ["Nameplate Detection"] = "Rilevamento tramite barre",
    ["This feature requires that |cFFFFD100Show Enemy Nameplates|r and |cFFFFD100Show All Nameplates|r are both enabled."] = "Questa funzione richiede che |cFFFFD100Mostra barre dei nemici|r e |cFFFFD100Mostra tutte le barre|r siano entrambe attivate.",
    ["Show Enemy Nameplates"] = "Mostra barre dei nemici",
    ["If checked, enemy nameplates will be displayed and can be used to count enemy targets."] = "Se selezionato, le barre dei nemici verranno mostrate e potranno essere usate per contare i bersagli nemici.",
    ["Show All Nameplates"] = "Mostra tutte le barre",
    ["If checked, all enemy nameplates (rather than just your target) will be displayed and can be used to count enemy targets."] = "Se selezionato, tutte le barre dei nemici (non solo quella del tuo bersaglio) verranno mostrate e potranno essere usate per contare i bersagli nemici.",
    ["Enemy Range Radius"] = "Raggio di distanza dei nemici",
    ["If |cFFFFD100Count Nameplates|r is enabled, enemies within this range will be included in target counts. Beyond 10 yards, only enemies in combat are counted.\n\nThis setting is only available if |cFFFFD100Show Enemy Nameplates|r and |cFFFFD100Show All Nameplates|r are both enabled."] = "Se |cFFFFD100Conta le barre dei nemici|r è attivo, i nemici entro questa distanza verranno inclusi nel conteggio dei bersagli. Oltre i 10 metri vengono contati solo i nemici in combattimento.\n\nQuesta impostazione è disponibile solo se |cFFFFD100Mostra barre dei nemici|r e |cFFFFD100Mostra tutte le barre|r sono entrambe attivate.",
    ["Allow Target Swaps |TInterface\\Addons\\Hekili\\Textures\\Cycle:0|t"] = "Consenti cambi bersaglio |TInterface\\Addons\\Hekili\\Textures\\Cycle:0|t",
    ["When target swapping is enabled, an icon (|TInterface\\Addons\\Hekili\\Textures\\Cycle:0|t) may be shown when you should use an ability on a different target.\n\nThis works well for some specs that simply want to apply a debuff to another target, but can be less-effective for specializations that are concerned with maintaining dots/debuffs based on their durations.\n\nThis feature is targeted for improvement in a future update."] = "Quando il cambio bersaglio è attivo, può comparire un'icona (|TInterface\\Addons\\Hekili\\Textures\\Cycle:0|t) quando dovresti usare un'abilità su un altro bersaglio.\n\nFunziona bene per alcune specializzazioni che vogliono semplicemente applicare una penalità a un altro bersaglio, ma può essere meno efficace per quelle che devono mantenere DOT/penalità in base alla loro durata.\n\nQuesta funzione sarà migliorata in un aggiornamento futuro.",
    ["Secondary Targets"] = "Bersagli secondari",
    ["Filter by Time-to-Die"] = "Filtra per tempo di morte",
    ["When |cffffd100Recommend Target Swaps|r is checked, this value determines which targets are counted for target swapping purposes.  If set to 5, target swapping will not be recommended if no other target will live 5 seconds or longer.  This can be beneficial to avoid applying damage-over-time effects to a target that will die too quickly to be damaged by them.\n\nSet to 0 to count all detected targets."] = "Quando |cffffd100Consiglia cambi bersaglio|r è selezionato, questo valore determina quali bersagli vengono contati per i cambi bersaglio.  Se è 5, il cambio bersaglio non verrà consigliato se nessun altro bersaglio vivrà 5 secondi o più.  Può servire a evitare di applicare effetti di danno nel tempo a un bersaglio che morirà troppo in fretta per subirli.\n\nImposta a 0 per contare tutti i bersagli rilevati.",
    ["Minimum Targets for Dedicated AOE Recommendations"] = "Bersagli minimi per le raccomandazioni AOE dedicate",
    ["Performance"] = "Prestazioni",
    ["Frame Budget"] = "Budget per fotogramma",
    ["This setting determines how much time can be used to calculate recommendations."] = "Questa impostazione determina quanto tempo si può usare per calcolare le raccomandazioni.",
    ["\nThis setting determines how much time can be used to generate recommendations.\n\n|cFFFFD100• Higher values|r allow recommendations to |cFF00FF00update more quickly|r but may risk lowering your frame rate, especially when other addons are working at the same time.\n|cFFFFD100• Lower values|r mean recommendations may update more slowly but may |cFF00FF00preserve your frame rate|r.\n\nAdjust this budget to balance |cFF00FF00smooth gameplay|r and |cFF00FF00responsive recommendations|r. Use the highest value that feels smooth on your system without your screen freezing or stuttering.\n\n|cFF00B4FFDefault (recommended)|r: |cFFFFD10070%|r\n\n"] = "\nQuesta impostazione determina quanto tempo si può usare per generare le raccomandazioni.\n\n|cFFFFD100• Valori più alti|r permettono alle raccomandazioni di |cFF00FF00aggiornarsi più in fretta|r ma rischiano di abbassare i tuoi fotogrammi al secondo, soprattutto quando altri addon lavorano nello stesso momento.\n|cFFFFD100• Valori più bassi|r fanno aggiornare le raccomandazioni più lentamente ma possono |cFF00FF00preservare i tuoi fotogrammi al secondo|r.\n\nRegola questo budget per bilanciare |cFF00FF00gioco fluido|r e |cFF00FF00raccomandazioni reattive|r. Usa il valore più alto che sul tuo sistema resta fluido senza blocchi o scatti dello schermo.\n\n|cFF00B4FFPredefinito (consigliato)|r: |cFFFFD10070%|r\n\n",
    ["At |cFFFFD700%.1f FPS|r, a budget of |cFFFFD700%s%%|r allows up to |cFFFFD700%.2f ms|r of frame time per update. Recommendations that take longer to calculate will be delayed by at least 1 frame."] = "A |cFFFFD700%.1f FPS|r, un budget del |cFFFFD700%s%%|r consente fino a |cFFFFD700%.2f ms|r di tempo di fotogramma per aggiornamento. Le raccomandazioni che richiedono più tempo per essere calcolate saranno ritardate di almeno 1 fotogramma.",
    ["Forecast"] = "Previsione",
    ["Forecast window (s)"] = "Finestra di previsione (s)",
    ["How far ahead the recommendations look for the next affordable action. A resource paid by swings can take longer to arrive than one that regenerates steadily; raise it if the queue sits empty while that resource builds."] = "Quanto in avanti le raccomandazioni guardano per trovare la prossima azione sostenibile. Una risorsa pagata dai colpi può arrivare più tardi di una che si rigenera in modo costante; alzala se la coda resta vuota mentre quella risorsa si accumula.",
    ["\nThis setting determines how far ahead the Primary and AOE recommendations look for the next affordable action, and how far the resource forecast runs.\n\n|cFFFFD100• Higher values|r show the next action while a resource paid by swings is still building, so the queue |cFF00FF00stays filled at the pull|r, at a small cost per recommendation that grows with the window.\n|cFFFFD100• Lower values|r |cFF00FF00cost less|r and suit a resource that regenerates steadily.\n\nThe other displays (Cooldowns, Defensives, Interrupts) keep their own |cFFFFD100Forecast Period|r in their display settings.\n\n|cFF00B4FFDefault|r: |cFFFFD10015 s|r\n\n"] = "\nQuesta impostazione determina quanto in avanti le raccomandazioni Principale e AOE guardano per trovare la prossima azione sostenibile, e fin dove arriva la previsione delle risorse.\n\n|cFFFFD100• Valori più alti|r mostrano l'azione successiva mentre una risorsa pagata dai colpi si sta ancora accumulando, così la coda |cFF00FF00resta piena all'inizio dello scontro|r, con un piccolo costo per raccomandazione che cresce con la finestra.\n|cFFFFD100• Valori più bassi|r |cFF00FF00costano meno|r e vanno bene per una risorsa che si rigenera in modo costante.\n\nGli altri riquadri (Cooldown, Difese, Interruzioni) mantengono il proprio |cFFFFD100Periodo di previsione|r nelle impostazioni del riquadro.\n\n|cFF00B4FFPredefinito|r: |cFFFFD10015 s|r\n\n",
    ["Current window: |cFF00FF00%s s|r"] = "Finestra attuale: |cFF00FF00%s s|r",
    ["%s Preferences"] = "Preferenze di %s",
    ["No priorities on Forever for %s: Hekili Forever recommends nothing while this specialization is active."] = "Nessuna priorità su Forever per %s: Hekili Forever non consiglia nulla finché questa specializzazione è attiva.",
    ["Priorities"] = "Priorità",
    ["Priorities (or action packs) are bundles of action lists used to make recommendations for each specialization."] = "Le priorità (o pacchetti di azioni) sono gruppi di liste di azioni usati per fare le raccomandazioni per ogni specializzazione.",
    ["Priorities (or action packs) are bundles of action lists used to make recommendations for each specialization.  They can be customized and shared.  |cFFFF0000Imported SimulationCraft priorities often require some translation before they will work with this addon.  No support is offered for customized or imported priorities.|r"] = "Le priorità (o pacchetti di azioni) sono gruppi di liste di azioni usati per fare le raccomandazioni per ogni specializzazione.  Possono essere personalizzate e condivise.  |cFFFF0000Le priorità importate da SimulationCraft spesso richiedono un po' di traduzione prima di funzionare con questo addon.  Non viene offerto alcun supporto per le priorità personalizzate o importate.|r",
    ["Create a New Priority"] = "Crea una nuova priorità",
    ["Priority Name"] = "Nome della priorità",
    ["Enter a new, unique name for this package.  Only alphanumeric characters, spaces, underscores, and apostrophes are allowed."] = "Inserisci un nome nuovo e unico per questo pacchetto.  Sono ammessi solo caratteri alfanumerici, spazi, trattini bassi e apostrofi.",
    ["Please specify a unique pack name."] = "Specifica un nome di pacchetto unico.",
    ["UseItems is a reserved name."] = "UseItems è un nome riservato.",
    ["Don't get smart, missy."] = "Non fare il furbo, signorina.",
    ["Only alphanumeric characters, spaces, underscores, and apostrophes are allowed in pack names."] = "Nei nomi dei pacchetti sono ammessi solo caratteri alfanumerici, spazi, trattini bassi e apostrofi.",
    ["Specialization"] = "Specializzazione",
    ["Create New Pack"] = "Crea nuovo pacchetto",
    ["Import / Export"] = "Importa / Esporta",
    ["Priorities can be Imported or Exported using encoded strings."] = "Le priorità si possono importare o esportare con stringhe codificate.",
    ["|cFF1EFF00Import / Export|r"] = "|cFF1EFF00Importa / Esporta|r",
    ["|cFFFF0000No support is offered for custom or imported priorities from elsewhere.|r\n\n|cFF00CCFFThe default priorities included within the addon are kept up to date, are compatible with your character, and do not require additional changes.|r\n\nPaste a Priority import string in the box below to begin."] = "|cFFFF0000Non viene offerto alcun supporto per priorità personalizzate o importate da altre fonti.|r\n\n|cFF00CCFFLe priorità predefinite incluse nell'addon sono tenute aggiornate, sono compatibili con il tuo personaggio e non richiedono altre modifiche.|r\n\nIncolla una stringa di importazione di una Priorità nella casella qui sotto per cominciare.",
    ["Import Priority"] = "Importa priorità",
    ["Pack Name"] = "Nome del pacchetto",
    ["Pack Date"] = "Data del pacchetto",
    ["Pack Specialization"] = "Specializzazione del pacchetto",
    ["No Specialization Set"] = "Nessuna specializzazione impostata",
    ["The imported Priority has no lists included."] = "La Priorità importata non contiene liste.",
    ["The imported Priority has one action list:  %s."] = "La Priorità importata ha una lista di azioni:  %s.",
    ["The imported Priority has two action lists:  %s and %s."] = "La Priorità importata ha due liste di azioni:  %s e %s.",
    ["The imported Priority has the following lists included:  "] = "La Priorità importata include queste liste:  ",
    ["%s, and %s."] = "%s e %s.",
    ["Select a Priority pack to export."] = "Scegli un pacchetto di Priorità da esportare.",
    ["Priority Export String"] = "Stringa di esportazione della priorità",
    ["Press CTRL+A to select, then CTRL+C to copy."] = "Premi CTRL+A per selezionare, poi CTRL+C per copiare.",
    ["Summary"] = "Riepilogo",
    ["This is a default priority package.  It will be automatically updated when the addon is updated.  If you want to customize this priority, make a copy by clicking |TInterface\\Addons\\Hekili\\Textures\\WhiteCopy:0|t.|r"] = "Questo è un pacchetto di priorità predefinito.  Verrà aggiornato automaticamente quando l'addon viene aggiornato.  Se vuoi personalizzare questa priorità, fanne una copia cliccando su |TInterface\\Addons\\Hekili\\Textures\\WhiteCopy:0|t.|r",
    ["Active"] = "Attiva",
    ["If checked, the addon's recommendations for this specialization are based on this priority package."] = "Se selezionato, le raccomandazioni dell'addon per questa specializzazione si basano su questo pacchetto di priorità.",
    ["Only alphanumeric characters, spaces, parentheses, underscores, and apostrophes are allowed in pack names."] = "Nei nomi dei pacchetti sono ammessi solo caratteri alfanumerici, spazi, parentesi, trattini bassi e apostrofi.",
    ["Copy Priority"] = "Copia priorità",
    ["Create a copy of this priority pack?"] = "Creare una copia di questo pacchetto di priorità?",
    ["Reload Priority"] = "Ricarica priorità",
    ["Reload this priority pack from defaults?"] = "Ricaricare questo pacchetto di priorità dai valori predefiniti?",
    ["Delete Priority"] = "Elimina priorità",
    ["Delete this priority package?"] = "Eliminare questo pacchetto di priorità?",
    ["Description"] = "Descrizione",
    ["Source"] = "Fonte",
    ["If this Priority was generated with a SimulationCraft profile, the profile can be stored or retrieved here.  The profile can also be re-imported or overwritten with a newer profile."] = "Se questa Priorità è stata generata da un profilo SimulationCraft, il profilo si può conservare o recuperare qui.  Il profilo si può anche reimportare o sovrascrivere con uno più recente.",
    ["If the Priority is based on a SimulationCraft profile or a popular guide, it is a good idea to provide a link to the source (especially before sharing)."] = "Se la Priorità si basa su un profilo SimulationCraft o su una guida popolare, è bene indicare un link alla fonte (soprattutto prima di condividerla).",
    ["Author"] = "Autore",
    ["The author field is automatically filled out when creating a new Priority.  You can update it here."] = "Il campo autore viene compilato in automatico quando crei una nuova Priorità.  Qui puoi aggiornarlo.",
    ["Last Updated"] = "Ultimo aggiornamento",
    ["This date is automatically updated when any changes are made to the action lists for this Priority."] = "Questa data si aggiorna automaticamente quando vengono fatte modifiche alle liste di azioni di questa Priorità.",
    ["Priority (SimulationCraft Action Priority List)"] = "Priorità (lista di priorità delle azioni SimulationCraft)",
    ["If this pack's action lists were imported from a SimulationCraft profile, the profile is included here."] = "Se le liste di azioni di questo pacchetto sono state importate da un profilo SimulationCraft, il profilo è incluso qui.",
    ["Changes will not be applied until Import is clicked."] = "Le modifiche non verranno applicate finché non clicchi Importa.",
    ["|cFFFF0000You do not need to import a SimulationCraft profile to use this addon. No support is offered for custom or imported priorities from elsewhere.|r\n\n|cFF00CCFFThe default priorities included within the addon are kept up to date, are compatible with your character, and do not require additional changes.|r\n\n"] = "|cFFFF0000Non serve importare un profilo SimulationCraft per usare questo addon. Non viene offerto alcun supporto per priorità personalizzate o importate da altre fonti.|r\n\n|cFF00CCFFLe priorità predefinite incluse nell'addon sono tenute aggiornate, sono compatibili con il tuo personaggio e non richiedono altre modifiche.|r\n\n",
    ["%sImport"] = "%sImporta",
    ["Clear existing action list(s) and load the priority above."] = "Cancella le liste di azioni esistenti e carica la priorità qui sopra.",
    ["You must be in the |T%d:0|t |cFFFFD100%s|r specialization to import this priority."] = "Devi essere nella specializzazione |T%d:0|t |cFFFFD100%s|r per importare questa priorità.",
    ["\n|cFF00CCFFBefore trying to import a profile, please consider the following:|r\n\n |cFFFFD100•|r SimulationCraft action lists tend not to change significantly for individual characters.  The profiles are written to include conditions that work for all gear, talent, and other factors combined.\n\n |cFFFFD100•|r Most SimulationCraft action lists require some additional customization to work with the addon.  For example, |cFFFFD100target_if|r conditions don't translate directly to the addon and have to be rewritten.\n\n |cFFFFD100•|r Some SimulationCraft action profiles are revised for the addon to be more efficient and use less processing time.\n\n |cFFFFD100•|r This feature has been left in for tinkerers and advanced users.\n\n"] = "\n|cFF00CCFFPrima di provare a importare un profilo, tieni presente quanto segue:|r\n\n |cFFFFD100•|r Le liste di azioni di SimulationCraft di solito non cambiano molto per i singoli personaggi.  I profili sono scritti con condizioni che valgono per tutti gli equipaggiamenti, talenti e altri fattori insieme.\n\n |cFFFFD100•|r La maggior parte delle liste di azioni SimulationCraft richiede qualche personalizzazione in più per funzionare con l'addon.  Per esempio, le condizioni |cFFFFD100target_if|r non si traducono direttamente nell'addon e vanno riscritte.\n\n |cFFFFD100•|r Alcuni profili di azioni SimulationCraft sono rivisti perché l'addon sia più efficiente e usi meno tempo di elaborazione.\n\n |cFFFFD100•|r Questa funzione è stata lasciata per chi ama sperimentare e per gli utenti esperti.\n\n",
    ["Import Log"] = "Registro di importazione",
    ["Action Lists"] = "Liste di azioni",
    ["Action Lists are used to determine which abilities should be used at what time."] = "Le liste di azioni servono a stabilire quali abilità usare e quando.",
    ["Action List"] = "Lista di azioni",
    ["Select the action list to view or modify."] = "Scegli la lista di azioni da vedere o modificare.",
    ["Create a New Action List"] = "Crea una nuova lista di azioni",
    ["Delete this Action List"] = "Elimina questa lista di azioni",
    ["Delete this action list?"] = "Eliminare questa lista di azioni?",
    ["Entry"] = "Voce",
    ["Select the entry to modify in this action list.\n\nEntries in red are disabled, have no action set, have a conditional error, or use actions that are disabled/toggled off."] = "Scegli la voce da modificare in questa lista di azioni.\n\nLe voci in rosso sono disattivate, non hanno un'azione impostata, hanno un errore nella condizione o usano azioni disattivate/spente.",
    ["Unassigned"] = "Non assegnato",
    ["reset |cff00ccff%s|r"] = "reimposta |cff00ccff%s|r",
    ["unassigned"] = "non assegnato",
    ["|cff00ccff%s|r default = |cffffd100%s|r"] = "|cff00ccff%s|r predefinito = |cffffd100%s|r",
    ["set |cff00ccff%s|r = |cffffd100%s|r"] = "imposta |cff00ccff%s|r = |cffffd100%s|r",
    ["nothing"] = "niente",
    ["%s, if |cffffd100%s|r"] = "%s, se |cffffd100%s|r",
    ["|cff00ccff(not set)|r"] = "|cff00ccff(non impostato)|r",
    ["|cff00ccff(not found)|r"] = "|cff00ccff(non trovato)|r",
    ["Delete this entry?"] = "Eliminare questa voce?",
    ["If disabled, this entry will not be shown even if its criteria are met."] = "Se disattivata, questa voce non verrà mostrata anche se i suoi criteri sono soddisfatti.",
    ["Action"] = "Azione",
    ["Select the action that will be recommended when this entry's criteria are met."] = "Scegli l'azione che verrà consigliata quando i criteri di questa voce sono soddisfatti.",
    ["Buff Name"] = "Nome del potenziamento",
    ["Specify the buff to remove."] = "Indica il potenziamento da rimuovere.",
    ["Window Name"] = "Nome della finestra",
    ["Specify the rotation window to open or close."] = "Indica la finestra di rotazione da aprire o chiudere.",
    ["Action Name"] = "Nome dell'azione",
    ["Specify the action to cancel; the result is that the addon will allow the channel to be removed immediately."] = "Indica l'azione da annullare; il risultato è che l'addon permetterà di interrompere subito il canale.",
    ["Seconds"] = "Secondi",
    ["Max Energy"] = "Energia massima",
    ["When checked, this entry will require that the player have enough energy to trigger Ferocious Bite's full damage bonus."] = "Se selezionato, questa voce richiederà che il giocatore abbia abbastanza energia per ottenere il bonus di danno completo di Morso feroce.",
    ["Caption"] = "Didascalia",
    ["Captions are |cFFFF0000very|r short descriptions that can appear on the icon of a recommended ability.\n\nThis can be useful for understanding why an ability was recommended at a particular time.\n\nRequires Captions to be enabled on each display."] = "Le didascalie sono descrizioni |cFFFF0000molto|r brevi che possono comparire sull'icona di un'abilità consigliata.\n\nPossono servire a capire perché un'abilità è stata consigliata in un dato momento.\n\nRichiede che le Didascalie siano attivate su ogni riquadro.",
    ["Caption text should be 20 characters or less."] = "Il testo della didascalia deve essere di 20 caratteri o meno.",
    ["Label"] = "Etichetta",
    ["Text shown on the recommendation while the Label Condition (if any) holds, e.g. a downranking note."] = "Testo mostrato sulla raccomandazione finché la Condizione dell'etichetta (se c'è) è vera, per esempio una nota sul rango ridotto.",
    ["Label Condition"] = "Condizione dell'etichetta",
    ["If entered, the Label shows only while this is true."] = "Se compilata, l'Etichetta viene mostrata solo finché questa è vera.",
    ["Icon"] = "Icona",
    ["A texture file ID or path to show on the recommendation in place of the ability's icon while the Icon Condition (if any) holds. A path is resolved when the list loads; a bare file ID is not checked."] = "L'ID di un file di texture o un percorso da mostrare sulla raccomandazione al posto dell'icona dell'abilità finché la Condizione dell'icona (se c'è) è vera. Un percorso viene risolto quando la lista si carica; un ID di file semplice non viene controllato.",
    ["Not a texture file; this line's icon is not overridden."] = "Non è un file di texture; l'icona di questa riga non viene sostituita.",
    ["Icon Condition"] = "Condizione dell'icona",
    ["If entered, the Icon shows only while this is true."] = "Se compilata, l'Icona viene mostrata solo finché questa è vera.",
    ["This allows you to provide text that explains this entry, which will show when you Pause and mouseover the ability to see why this entry was recommended."] = "Qui puoi scrivere un testo che spiega questa voce, che verrà mostrato quando metti in Pausa e passi il mouse sull'abilità per vedere perché questa voce è stata consigliata.",
    ["Variable Name"] = "Nome della variabile",
    ["Specify a name for this variable.  Variables must be lowercase with no spaces or symbols aside from the underscore."] = "Indica un nome per questa variabile.  Le variabili devono essere in minuscolo, senza spazi né simboli a parte il trattino basso.",
    ["Variables must be at least 3 characters in length."] = "Le variabili devono essere lunghe almeno 3 caratteri.",
    ["Invalid characters entered.  Try again."] = "Caratteri non validi.  Riprova.",
    ["Operation"] = "Operazione",
    ["Add Value"] = "Aggiungi valore",
    ["Ceiling of Value"] = "Arrotonda il valore per eccesso",
    ["Set Default Value"] = "Imposta valore predefinito",
    ["Divide Value"] = "Dividi valore",
    ["Floor of Value"] = "Arrotonda il valore per difetto",
    ["Maximum of Values"] = "Massimo dei valori",
    ["Minimum of Values"] = "Minimo dei valori",
    ["Modulo of Value"] = "Modulo del valore",
    ["Multiply Value"] = "Moltiplica valore",
    ["Raise Value to X Power"] = "Eleva il valore alla potenza X",
    ["Reset to Default"] = "Reimposta al predefinito",
    ["Set Value"] = "Imposta valore",
    ["Set Value If..."] = "Imposta valore se...",
    ["Subtract Value"] = "Sottrai valore",
    ["Not Set"] = "Non impostato",
    ["Pool for Next Entry (%s)"] = "Accumula per la voce successiva (%s)",
    ["If checked, the addon will pool resources until the next entry has enough resources to use."] = "Se selezionato, l'addon accumulerà risorse finché la voce successiva avrà abbastanza risorse da usare.",
    ["Pooling Time"] = "Tempo di accumulo",
    ["Specify the time, in seconds, as a number or as an expression that evaluates to a number.\nDefault is |cFFFFD1000.5|r.  An example expression would be |cFFFFD100energy.time_to_max|r."] = "Indica il tempo, in secondi, come numero o come espressione che dà un numero.\nIl valore predefinito è |cFFFFD1000.5|r.  Un esempio di espressione è |cFFFFD100energy.time_to_max|r.",
    ["Extra Pooling"] = "Accumulo extra",
    ["Specify the amount of extra resources to pool in addition to what is needed for the next entry."] = "Indica la quantità di risorse extra da accumulare oltre a quelle necessarie per la voce successiva.",
    ["Conditions"] = "Condizioni",
    ["Specify Conditions that must be met for this action to be recommended or used in generating recommendations."] = "Indica le Condizioni che devono essere soddisfatte perché questa azione venga consigliata o usata nel generare le raccomandazioni.",
    ["Value"] = "Valore",
    ["Provide the value to store (or calculate) when this variable is invoked.\n\nIf Conditions are provided, this value is set when Conditions are met."] = "Indica il valore da memorizzare (o calcolare) quando questa variabile viene richiamata.\n\nSe sono indicate delle Condizioni, questo valore viene impostato quando le Condizioni sono soddisfatte.",
    ["Value when Conditions are Not Met"] = "Valore quando le Condizioni non sono soddisfatte",
    ["Provide the value to store (or calculate) if Conditions are not met."] = "Indica il valore da memorizzare (o calcolare) se le Condizioni non sono soddisfatte.",
    ["Show Unused Modifiers (if applicable)"] = "Mostra i modificatori inutilizzati (se applicabile)",
    ["If checked, additional modifiers that are not currently used by this entry."] = "Se selezionato, mostra i modificatori aggiuntivi che questa voce non usa al momento.",
    ["Cycle Targets"] = "Cicla i bersagli",
    ["If checked, the addon will check each available target and show whether to switch targets."] = "Se selezionato, l'addon controllerà ogni bersaglio disponibile e mostrerà se conviene cambiare bersaglio.",
    ["Max Cycle Targets"] = "Massimo di bersagli da ciclare",
    ["If cycle targets is checked, the addon will check up to the specified number of targets."] = "Se cicla i bersagli è selezionato, l'addon controllerà fino al numero di bersagli indicato.",
    ["Check Movement"] = "Controlla il movimento",
    ["If checked, this entry can only be recommended when your character movement matches the setting."] = "Se selezionato, questa voce può essere consigliata solo quando il movimento del tuo personaggio corrisponde all'impostazione.",
    ["Movement"] = "Movimento",
    ["If set, this entry can only be recommended when your movement matches the setting."] = "Se impostato, questa voce può essere consigliata solo quando il tuo movimento corrisponde all'impostazione.",
    ["Stationary"] = "Fermo",
    ["Moving"] = "In movimento",
    ["Use Off GCD"] = "Usa fuori dal GCD",
    ["If checked, this entry can be checked even if the global cooldown (GCD) is active."] = "Se selezionato, questa voce può essere controllata anche quando il cooldown globale (GCD) è attivo.",
    ["Use While Casting"] = "Usa mentre lanci",
    ["If checked, this entry can be checked even if you are already casting or channeling."] = "Se selezionato, questa voce può essere controllata anche se stai già lanciando o canalizzando.",
    ["During Channel"] = "Durante un canale",
    ["If checked, this entry can only be used if you are channeling another spell."] = "Se selezionato, questa voce può essere usata solo se stai canalizzando un altro incantesimo.",
    ["Focus Tier"] = "Livello di focus",
    ["Timeline style: 0 is off; a tier (1 highest) makes this entry a focus candidate. When it is predicted within the focus horizon it takes the Now circle; the lowest tier wins, then the soonest."] = "Stile cronologia: 0 è disattivato; un livello (1 il più alto) rende questa voce una candidata al focus. Quando è prevista entro l'orizzonte del focus prende il cerchio \"ora\"; vince il livello più basso, poi la più vicina nel tempo.",
    ["Entry Cooldown"] = "Cooldown della voce",
    ["If set, this entry cannot be recommended unless this time has passed since the last time the ability was used."] = "Se impostato, questa voce non può essere consigliata finché non è passato questo tempo dall'ultima volta che l'abilità è stata usata.",
    ["Test Conditions Immediately"] = "Verifica subito le condizioni",
    ["If checked, the Conditions (above) must be met immediately for this action to be recommended or used."] = "Se selezionato, le Condizioni (sopra) devono essere soddisfatte subito perché questa azione venga consigliata o usata.",
    ["Additional Immediate Criteria"] = "Criteri immediati aggiuntivi",
    ["If entered, these Immediate Criteria must be met before the Conditions above will be tested."] = "Se compilati, questi Criteri immediati devono essere soddisfatti prima che vengano verificate le Condizioni qui sopra.",
    ["List Name"] = "Nome della lista",
    ["Action list names should be at least 2 characters in length."] = "I nomi delle liste di azioni devono essere lunghi almeno 2 caratteri.",
    ["There is already an action list by that name."] = "Esiste già una lista di azioni con questo nome.",
    ["Only alphanumeric characters and underscores can be used in list names."] = "Nei nomi delle liste si possono usare solo caratteri alfanumerici e trattini bassi.",
    ["Add List"] = "Aggiungi lista",
    ["Cancel"] = "Annulla",
    ["Create New Entry"] = "Crea nuova voce",
    ["|cff777777<No message provided>|r"] = "|cff777777<Nessun messaggio fornito>|r",
    ["|cffa0a0ffAutomatic Stress Test:|r "] = "|cffa0a0ffTest di stress automatico:|r ",
    ["|cffff0000WARNING:|r There are unresolved Warnings related to this priority. Please review before exporting."] = "|cffff0000ATTENZIONE:|r Ci sono Avvisi non risolti relativi a questa priorità. Controllali prima di esportare.",
    ["|cffffff00NOTICE:|r There are unresolved Warnings since reloading the UI. These may not be related to this priority."] = "|cffffff00NOTA:|r Ci sono Avvisi non risolti dal ricaricamento dell'interfaccia. Potrebbero non essere collegati a questa priorità.",
    ["|cff00ff00No warnings or errors detected!|r\n"] = "|cff00ff00Nessun avviso o errore rilevato!|r\n",
    ["Stress Test Results"] = "Risultati del test di stress",
    ["Toggles"] = "Interruttori",
    ["Toggles are keybindings that can be used to control which abilities may be recommended and where they are displayed."] = "Gli interruttori sono scorciatoie da tastiera che servono a controllare quali abilità possono essere consigliate e dove vengono mostrate.",
    ["Damage Cooldowns"] = "Cooldown di danno",
    ["Toggle Major and Minor Cooldowns to ensure they are recommended at ideal times."] = "Attiva o disattiva i Cooldown maggiori e minori per assicurarti che vengano consigliati nei momenti ideali.",
    ["Major Cooldowns"] = "Cooldown maggiori",
    ["Set a key to toggle recommendations of Major Cooldowns on or off."] = "Imposta un tasto per attivare o disattivare le raccomandazioni dei Cooldown maggiori.",
    ["Enable Major Cooldowns"] = "Attiva i Cooldown maggiori",
    ["If checked, abilities and items that require the |cFFFFD100Major Cooldowns|r toggle can be recommended.\n\nThis toggle generally applies to major damage abilities with cooldowns of 60 seconds or greater.\n\nAbilities may be added/removed from this toggle in |cFFFFD100Abilities|r and/or |cFFFFD100Gear and Items|r sections."] = "Se selezionato, possono essere consigliate le abilità e gli oggetti che richiedono l'interruttore |cFFFFD100Cooldown maggiori|r.\n\nQuesto interruttore vale in genere per le abilità di danno maggiori con cooldown di 60 secondi o più.\n\nPuoi aggiungere/togliere abilità da questo interruttore nelle sezioni |cFFFFD100Abilità|r e/o |cFFFFD100Equipaggiamento e oggetti|r.",
    ["Show in Separate %s Cooldowns Display"] = "Mostra nel riquadro Cooldown %s separato",
    ["If checked, abilities controlled by this toggle will be shown separately in your |W%s |cFFFFD100Major Cooldowns|r|w display when the toggle is enabled.\n\nThis is an experimental feature and may not work well for some specializations."] = "Se selezionato, le abilità controllate da questo interruttore verranno mostrate separatamente nel tuo riquadro |W%s |cFFFFD100Cooldown maggiori|r|w quando l'interruttore è attivo.\n\nÈ una funzione sperimentale e potrebbe non funzionare bene per alcune specializzazioni.",
    ["Active During %s"] = "Attivo durante %s",
    ["If checked, when any %s effect is active, the |cFFFFD100Major Cooldowns|r toggle will be treated as enabled, even if unchecked."] = "Se selezionato, quando un qualsiasi effetto %s è attivo, l'interruttore |cFFFFD100Cooldown maggiori|r verrà considerato attivo, anche se non selezionato.",
    ["If checked, when %s is active, the |cFFFFD100Major Cooldowns|r toggle will be treated as enabled, even if unchecked."] = "Se selezionato, quando %s è attivo, l'interruttore |cFFFFD100Cooldown maggiori|r verrà considerato attivo, anche se non selezionato.",
    ["Minor Cooldowns"] = "Cooldown minori",
    ["Set a key to toggle recommendations of Minor Cooldowns on or off."] = "Imposta un tasto per attivare o disattivare le raccomandazioni dei Cooldown minori.",
    ["Enable Minor Cooldowns"] = "Attiva i Cooldown minori",
    ["If checked, abilities that require the |cFFFFD100Minor Cooldowns|r toggle can be recommended.\n\nThis toggle generally applies to damage-boosting abilities with a cooldown of 30 to 60 seconds, or abilities that you may want to control separately from your major cooldowns.\n\nAbilities may be added/removed from this toggle in |cFFFFD100Abilities|r and/or |cFFFFD100Gear and Items|r sections."] = "Se selezionato, possono essere consigliate le abilità che richiedono l'interruttore |cFFFFD100Cooldown minori|r.\n\nQuesto interruttore vale in genere per le abilità che aumentano il danno con un cooldown da 30 a 60 secondi, o per le abilità che vuoi controllare separatamente dai cooldown maggiori.\n\nPuoi aggiungere/togliere abilità da questo interruttore nelle sezioni |cFFFFD100Abilità|r e/o |cFFFFD100Equipaggiamento e oggetti|r.",
    ["Auto-Enable when |cFFFFD100Major Cooldowns|r Active"] = "Attiva in automatico quando i |cFFFFD100Cooldown maggiori|r sono attivi",
    ["If checked, when |cFFFFD100Major Cooldowns|r are enabled (or auto-enabled), your |cFFFFD100Minor Cooldowns|r may be recommended even if the toggle itself is not checked."] = "Se selezionato, quando i |cFFFFD100Cooldown maggiori|r sono attivi (o attivati in automatico), i tuoi |cFFFFD100Cooldown minori|r possono essere consigliati anche se l'interruttore stesso non è selezionato.",
    ["Set a key to toggle recommendations of Potions on or off."] = "Imposta un tasto per attivare o disattivare le raccomandazioni delle Pozioni.",
    ["Enable Potions"] = "Attiva le pozioni",
    ["If checked, abilities that require the |cFFFFD100Potions|r toggle can be recommended."] = "Se selezionato, possono essere consigliate le abilità che richiedono l'interruttore |cFFFFD100Pozioni|r.",
    ["If checked, when |cFFFFD100Major Cooldowns|r are enabled (or auto-enabled), your |cFFFFD100Potions|r may be recommended even if the toggle itself is not checked."] = "Se selezionato, quando i |cFFFFD100Cooldown maggiori|r sono attivi (o attivati in automatico), le tue |cFFFFD100Pozioni|r possono essere consigliate anche se l'interruttore stesso non è selezionato.",
    ["Toggle whether priorities that move to reach the next ability show it out of range."] = "Imposta se le priorità che si muovono per raggiungere l'abilità successiva la mostrano fuori portata.",
    ["Set a key to toggle Movement on or off."] = "Imposta un tasto per attivare o disattivare il Movimento.",
    ["Enable Movement"] = "Attiva il movimento",
    ["If checked, a priority that moves to reach its next ability shows that ability while you are out of range, tinted as out of range. If unchecked, the ability is hidden until you are in range."] = "Se selezionato, una priorità che si muove per raggiungere la sua abilità successiva mostra quell'abilità mentre sei fuori portata, colorata come fuori portata. Se non selezionato, l'abilità resta nascosta finché non sei a portata.",
    ["Interrupts and Defensives"] = "Interruzioni e difese",
    ["Toggle Interrupts (and other utility) and Defensives as needed."] = "Attiva o disattiva Interruzioni (e altre utilità) e Difese secondo necessità.",
    ["Set a key to toggle recommendations of Interrupts (or utility abilities) on or off."] = "Imposta un tasto per attivare o disattivare le raccomandazioni delle Interruzioni (o delle abilità di utilità).",
    ["Enable Interrupts"] = "Attiva le interruzioni",
    ["If checked, abilities that require the |cFFFFD100Interrupts|r toggle can be recommended"] = "Se selezionato, possono essere consigliate le abilità che richiedono l'interruttore |cFFFFD100Interruzioni|r",
    ["Show in Separate %s Interrupts Display"] = "Mostra nel riquadro Interruzioni %s separato",
    ["If checked, abilities that require the |cFFFFD100Interrupts|r toggle will be shown separately in your %s Interrupts display."] = "Se selezionato, le abilità che richiedono l'interruttore |cFFFFD100Interruzioni|r verranno mostrate separatamente nel tuo riquadro Interruzioni %s.",
    ["Interrupt Timing"] = "Tempistica delle interruzioni",
    ["By default, interrupts are recommended when an enemy's cast has 0.25 seconds (or less) remaining.\n\nIf set to 2, an interrupt could be recommended when the cast has less than 2 seconds remaining."] = "Per impostazione predefinita, le interruzioni vengono consigliate quando al lancio di un nemico restano 0,25 secondi (o meno).\n\nSe è impostato a 2, un'interruzione può essere consigliata quando al lancio restano meno di 2 secondi.",
    ["Set a key to toggle recommendations of Defensives on or off.\n\nThis toggle applies primarily to Tank specializations."] = "Imposta un tasto per attivare o disattivare le raccomandazioni delle Difese.\n\nQuesto interruttore vale soprattutto per le specializzazioni Tank.",
    ["Enable Defensives"] = "Attiva le difese",
    ["If checked, abilities that require the |cFFFFD100Defensives|r toggle can be recommended.\n\nThis toggle applies primarily to Tank specializations."] = "Se selezionato, possono essere consigliate le abilità che richiedono l'interruttore |cFFFFD100Difese|r.\n\nQuesto interruttore vale soprattutto per le specializzazioni Tank.",
    ["Show in Separate %s Defensives Display"] = "Mostra nel riquadro Difese %s separato",
    ["If checked, defensive/mitigation abilities will be shown separately in your |W%s |cFFFFD100Defensives|r|w display.\n\nThis toggle applies primarily to Tank specializations."] = "Se selezionato, le abilità difensive/di mitigazione verranno mostrate separatamente nel tuo riquadro |W%s |cFFFFD100Difese|r|w.\n\nQuesto interruttore vale soprattutto per le specializzazioni Tank.",
    ["Display Control"] = "Controllo dei riquadri",
    ["Cycle through your preferred Display Modes using the keybinding you select."] = "Scorri le tue Modalità di visualizzazione preferite con la scorciatoia che scegli.",
    ["Display Mode"] = "Modalità di visualizzazione",
    ["Pressing this binding will cycle your Display Mode through the options checked below."] = "Premendo questa scorciatoia scorrerai la Modalità di visualizzazione tra le opzioni selezionate qui sotto.",
    ["Select Display Mode"] = "Scegli la modalità di visualizzazione",
    ["Select your Display Mode."] = "Scegli la tua Modalità di visualizzazione.",
    ["Automatic"] = "Automatica",
    ["Single-Target"] = "Bersaglio singolo",
    ["AOE (Multi-Target)"] = "AOE (più bersagli)",
    ["Fixed Dual Display"] = "Doppio riquadro fisso",
    ["Reactive Dual Display"] = "Doppio riquadro reattivo",
    ["Select the |cFFFFD100Display Modes|r that you wish to use.  Each time you press your |cFFFFD100Display Mode|r keybinding, the addon will switch to the next checked mode."] = "Scegli le |cFFFFD100Modalità di visualizzazione|r che vuoi usare.  Ogni volta che premi la scorciatoia della |cFFFFD100Modalità di visualizzazione|r, l'addon passerà alla modalità selezionata successiva.",
    ["(Default)"] = "(Predefinita)",
    ["If checked, the Display Mode toggle can select Automatic mode.\n\nThe Primary display shows recommendations based upon the detected number of enemies (based on your specialization's options)."] = "Se selezionato, l'interruttore Modalità di visualizzazione può scegliere la modalità Automatica.\n\nIl riquadro Principale mostra le raccomandazioni in base al numero di nemici rilevati (secondo le opzioni della tua specializzazione).",
    ["%s Uses Primary Display\n%s Recommendations based on Targets Detected"] = "%s Usa il riquadro Principale\n%s Raccomandazioni in base ai bersagli rilevati",
    ["If checked, the Display Mode toggle can select Single-Target mode.\n\nThe Primary display shows recommendations as though you have one target (even if more targets are detected)."] = "Se selezionato, l'interruttore Modalità di visualizzazione può scegliere la modalità Bersaglio singolo.\n\nIl riquadro Principale mostra le raccomandazioni come se avessi un solo bersaglio (anche se ne vengono rilevati di più).",
    ["%s Uses Primary Display\n%s Recommendations based on 1 Target\n%s Useful when Focusing Damage on a High-Priority Enemy"] = "%s Usa il riquadro Principale\n%s Raccomandazioni in base a 1 bersaglio\n%s Utile quando concentri il danno su un nemico ad alta priorità",
    ["If checked, the Display Mode toggle can select AOE mode.\n\nThe Primary display shows recommendations as though you have at least |cFFFFD100%d|r targets (even if fewer are detected).\n\nThe number of targets is set in your specialization's options."] = "Se selezionato, l'interruttore Modalità di visualizzazione può scegliere la modalità AOE.\n\nIl riquadro Principale mostra le raccomandazioni come se avessi almeno |cFFFFD100%d|r bersagli (anche se ne vengono rilevati meno).\n\nIl numero di bersagli si imposta nelle opzioni della tua specializzazione.",
    ["%s Uses Primary Display\n%s Recommendations based on at least |cFFFFD100%d|r Targets\n"] = "%s Usa il riquadro Principale\n%s Raccomandazioni in base ad almeno |cFFFFD100%d|r bersagli\n",
    ["Dual"] = "Doppio",
    ["If checked, the Display Mode toggle can select Dual mode.\n\nThe Primary display shows single-target recommendations and the AOE display shows recommendations for |cFFFFD100%d|r or more targets (even if fewer are detected).\n\nThe number of AOE targets is set in your specialization's options."] = "Se selezionato, l'interruttore Modalità di visualizzazione può scegliere la modalità Doppio.\n\nIl riquadro Principale mostra le raccomandazioni a bersaglio singolo e il riquadro AOE mostra le raccomandazioni per |cFFFFD100%d|r o più bersagli (anche se ne vengono rilevati meno).\n\nIl numero di bersagli AOE si imposta nelle opzioni della tua specializzazione.",
    ["%s Uses Two Displays: Primary and AOE\n%s Primary Display's Recommendations based on 1 Target\n%s AOE Display's Recommendations based on at least |cFFFFD100%d|r Targets\n%s Useful for Ranged Specializations using Damage-Based Target Detection\n"] = "%s Usa due riquadri: Principale e AOE\n%s Raccomandazioni del riquadro Principale in base a 1 bersaglio\n%s Raccomandazioni del riquadro AOE in base ad almeno |cFFFFD100%d|r bersagli\n%s Utile per le specializzazioni a distanza che usano il rilevamento dei bersagli basato sul danno\n",
    ["If checked, the Display Mode toggle can select Reactive mode.\n\nThe Primary display shows single-target recommendations, while the AOE display remains hidden until/unless |cFFFFD100%d|r or more targets are detected."] = "Se selezionato, l'interruttore Modalità di visualizzazione può scegliere la modalità Reattiva.\n\nIl riquadro Principale mostra le raccomandazioni a bersaglio singolo, mentre il riquadro AOE resta nascosto finché non vengono rilevati |cFFFFD100%d|r o più bersagli.",
    ["%s Uses Two Displays: Primary and AOE\n%s Primary Display's Recommendations based on 1 Target\n%s AOE Display Shown when |cFFFFD100%d|r+ Targets Detected"] = "%s Usa due riquadri: Principale e AOE\n%s Raccomandazioni del riquadro Principale in base a 1 bersaglio\n%s Riquadro AOE mostrato quando vengono rilevati |cFFFFD100%d|r+ bersagli",
    ["Troubleshooting"] = "Risoluzione dei problemi",
    ["These keybindings help provide critical information when troubleshooting or reporting issues."] = "Queste scorciatoie servono a fornire informazioni importanti quando si risolvono problemi o si segnalano errori.",
    ["Unpause"] = "Riprendi",
    ["Pause"] = "Pausa",
    ["Set a key to pause processing of your action lists. Your current display(s) will freeze, and you can mouseover each icon to see information about the displayed action.\n\nThis will also create a Snapshot that can be used for troubleshooting and error reporting."] = "Imposta un tasto per mettere in pausa l'elaborazione delle tue liste di azioni. I riquadri attuali si bloccano e puoi passare il mouse su ogni icona per vedere le informazioni sull'azione mostrata.\n\nCrea anche un'Istantanea che può servire per risolvere problemi e segnalare errori.",
    ["Snapshot"] = "Istantanea",
    ["Set a key to make a snapshot (without pausing) that can be viewed on the Snapshots tab.  This can be useful information for testing and debugging."] = "Imposta un tasto per creare un'istantanea (senza pausa) che si può consultare nella scheda Istantanee.  Può essere un'informazione utile per test e debug.",
    ["Custom Toggles"] = "Interruttori personalizzati",
    ["These toggles allow for the creation of custom keybindings to control specific abilities."] = "Questi interruttori permettono di creare scorciatoie personalizzate per controllare abilità specifiche.",
    ["Custom #1"] = "Personalizzato #1",
    ["Set a key to toggle your first custom set."] = "Imposta un tasto per attivare o disattivare il tuo primo gruppo personalizzato.",
    ["Enable Custom #1"] = "Attiva Personalizzato #1",
    ["If checked, abilities linked to Custom #1 can be recommended."] = "Se selezionato, possono essere consigliate le abilità collegate a Personalizzato #1.",
    ["Custom #1 Name"] = "Nome di Personalizzato #1",
    ["Specify a descriptive name for this custom toggle."] = "Indica un nome descrittivo per questo interruttore personalizzato.",
    ["Custom #2"] = "Personalizzato #2",
    ["Set a key to toggle your second custom set."] = "Imposta un tasto per attivare o disattivare il tuo secondo gruppo personalizzato.",
    ["Enable Custom #2"] = "Attiva Personalizzato #2",
    ["If checked, abilities linked to Custom #2 can be recommended."] = "Se selezionato, possono essere consigliate le abilità collegate a Personalizzato #2.",
    ["Custom #2 Name"] = "Nome di Personalizzato #2",
    ["Skeleton"] = "Scheletro",
    ["A rough skeleton of your current spec, for development purposes only."] = "Uno scheletro approssimativo della tua spec attuale, solo per scopi di sviluppo.",
    ["Generate Skeleton"] = "Genera scheletro",
    ["Warnings"] = "Avvisi",
    ["Warning Identifier"] = "Identificatore dell'avviso",
    ["Warning Information"] = "Informazioni sull'avviso",
    ["General"] = "Generale",
    ["Welcome to Hekili Forever; includes general information and essential links."] = "Benvenuto in Hekili Forever; comprende informazioni generali e link essenziali.",
    ["Enables or disables the addon."] = "Attiva o disattiva l'addon.",
    ["Hide Minimap Icon"] = "Nascondi l'icona della minimappa",
    ["If checked, the minimap icon will be hidden."] = "Se selezionato, l'icona della minimappa verrà nascosta.",
    ["Monitor Performance"] = "Monitora le prestazioni",
    ["If checked, the addon will track processing time and volume of events."] = "Se selezionato, l'addon terrà traccia del tempo di elaborazione e del volume degli eventi.",
    ["|cFF00CCFFHekili Forever|r is a fork of the original |cFFFFD100Hekili|r project, made with the explicit permission of its original author. It is based on the original work by Hekili and its maintainers, modified for WoW Forever by defzach from October 2026, and it is |cffff0000not|r the original project: please report problems on the Hekili Forever GitHub page below, never to the original Hekili authors.\n\nHekili Forever is free software under the GNU General Public License version 3 or (at your option) any later version; the full text is in the LICENSE file in the addon folder.\n\nSee the |cFFFFD100Snapshots (Troubleshooting)|r section for how to report a bug.\n\n"] = "|cFF00CCFFHekili Forever|r è un fork del progetto originale |cFFFFD100Hekili|r, realizzato con il permesso esplicito del suo autore originale. Si basa sul lavoro originale di Hekili e dei suoi manutentori, modificato per WoW Forever da defzach a partire da ottobre 2026, e |cffff0000non|r è il progetto originale: segnala i problemi nella pagina GitHub di Hekili Forever qui sotto, mai agli autori dell'Hekili originale.\n\nHekili Forever è software libero sotto la GNU General Public License versione 3 o (a tua scelta) qualsiasi versione successiva; il testo completo è nel file LICENSE nella cartella dell'addon.\n\nVedi la sezione |cFFFFD100Istantanee (Risoluzione dei problemi)|r per come segnalare un errore.\n\n",
    ["Find Hekili Forever updates on GitHub."] = "Trova gli aggiornamenti di Hekili Forever su GitHub.",
    ["Find Hekili Forever updates on CurseForge."] = "Trova gli aggiornamenti di Hekili Forever su CurseForge.",
    ["Report Issue"] = "Segnala un problema",
    ["APL Reference"] = "Riferimento APL",
    ["Getting Started"] = "Per iniziare",
    ["This section serves as a quick tutorial and explanation of the addon."] = "Questa sezione è un breve tutorial con la spiegazione dell'addon.",
    ["Welcome to Hekili Forever\n"] = "Benvenuto in Hekili Forever\n",
    ["This section is a quick overview of the addon basics. At the end, you will also find answers to a few of the most common questions we get on GitHub. \n\n|cFF00CCFFTaking a couple minutes to read it is highly encouraged to improve your experience!|r\n\n"] = "Questa sezione è una rapida panoramica dei concetti base dell'addon. Alla fine troverai anche le risposte ad alcune delle domande più frequenti che riceviamo su GitHub. \n\n|cFF00CCFFDedicare un paio di minuti a leggerla è caldamente consigliato per migliorare la tua esperienza!|r\n\n",
    ["How To Use Toggles"] = "Come usare gli interruttori",
    ["The addon has several |cFFFFD100Toggles|r available that help you control the type of recommendations you receive while in combat, which can be toggled via hotkeys.  See the |cFFFFD100Toggles|r section for specifics.\n\n|cFFFFD100Damage Cooldowns|r:  Your major DPS cooldowns are assigned to the |cFF00CCFFCooldowns|r toggle.  This allows you to enable/disable these abilities in combat by using a keybind, which can prevent the addon from recommending your important cooldowns in some undesireable scenarios such as: \n• At the end of a dungeon pack\n• During a raid boss invulnerability phase, or right before a bonus damage phase\n\nYou can add/remove abilities from these toggles in the |cFFFFD100Abilities|r or |cFFFFD100Gear and Items|r sections. \n\n|cFF00CCFFLearning to use the Cooldowns toggle while playing can greatly increase your dps!|r\n\n"] = "L'addon ha vari |cFFFFD100Interruttori|r che ti aiutano a controllare il tipo di raccomandazioni che ricevi in combattimento, e che si possono attivare con scorciatoie da tastiera.  Vedi la sezione |cFFFFD100Interruttori|r per i dettagli.\n\n|cFFFFD100Cooldown di danno|r:  I tuoi cooldown di DPS maggiori sono assegnati all'interruttore |cFF00CCFFCooldown|r.  Così puoi attivare/disattivare queste abilità in combattimento con una scorciatoia, evitando che l'addon consigli i tuoi cooldown importanti in situazioni poco adatte come: \n• Alla fine di un gruppo di mob in un dungeon\n• Durante una fase di invulnerabilità di un boss di raid, o subito prima di una fase di danno bonus\n\nPuoi aggiungere/togliere abilità da questi interruttori nelle sezioni |cFFFFD100Abilità|r o |cFFFFD100Equipaggiamento e oggetti|r. \n\n|cFF00CCFFImparare a usare l'interruttore Cooldown mentre giochi può aumentare di molto il tuo DPS!|r\n\n",
    ["Setting up your displays"] = "Configurare i riquadri",
    ["|cFFFFD100Displays|r are where Hekili Forever shows you the recommended spells and items to cast, with the |cFF00CCFFPrimary|r display being your DPS priority. When this options window is open, all displays are visible.\n\n|cFFFFD100Displays|r can be moved by:\n• Clicking and Dragging them\n  - You can move this window out of the way by clicking the |cFFFFD100Hekili Forever %s |rtitle at the very top and dragging it out of the way.\n  - Or, you can type |cFFFFD100/hek move|r to allow displays to be moved, but without opening the options. Type it again to lock the displays.\n• Setting precise X/Y positioning in the |cFFFFD100Displays|r section, on each display's |cFFFFD100Icon|r tab.\n\nBy default, the addon uses |cFFFFD100Automatic|r Mode, which decides whether to do a |cFF00CCFFSingle-Target|r or |cFF00CCFFAoE (Multi-Target)|r rotation based on the number of targets detected. You can enable other types of displays in the |cFFFFD100Toggles|r > |cFFFFD100Display Control|r section. There are also other types of displays you can use, with options to display them separately from your |cFF00CCFFPrimary|r display.\n\nAdditional Displays:\n• |cFF00CCFFCooldowns|r\n• |cFF00CCFFInterrupts|r\n• |cFF00CCFFDefensives|r\n\n"] = "I |cFFFFD100Riquadri|r sono i punti in cui Hekili Forever ti mostra gli incantesimi e gli oggetti consigliati da usare, con il riquadro |cFF00CCFFPrincipale|r che è la tua priorità di DPS. Quando questa finestra di opzioni è aperta, tutti i riquadri sono visibili.\n\nI |cFFFFD100Riquadri|r si possono spostare:\n• Cliccandoli e trascinandoli\n  - Puoi spostare questa finestra cliccando sul titolo |cFFFFD100Hekili Forever %s |rin alto e trascinandola via.\n  - Oppure puoi scrivere |cFFFFD100/hek move|r per poter spostare i riquadri senza aprire le opzioni. Scrivilo di nuovo per bloccare i riquadri.\n• Impostando la posizione precisa X/Y nella sezione |cFFFFD100Riquadri|r, nella scheda |cFFFFD100Icona|r di ogni riquadro.\n\nPer impostazione predefinita l'addon usa la modalità |cFFFFD100Automatica|r, che decide se fare una rotazione a |cFF00CCFFBersaglio singolo|r o |cFF00CCFFAOE (più bersagli)|r in base al numero di bersagli rilevati. Puoi attivare altri tipi di riquadri nella sezione |cFFFFD100Interruttori|r > |cFFFFD100Controllo dei riquadri|r. Ci sono anche altri tipi di riquadri che puoi usare, con opzioni per mostrarli separatamente dal riquadro |cFF00CCFFPrincipale|r.\n\nRiquadri aggiuntivi:\n• |cFF00CCFFCooldown|r\n• |cFF00CCFFInterruzioni|r\n• |cFF00CCFFDifese|r\n\n",
    ["Common questions and problems"] = "Domande e problemi comuni",
    ["Top 3 questions/problems\n\n1. My keybinds aren't showing up right\n- |cFF00CCFFThis can happen with macros or stealth bars sometimes. You can manually tell the addon what keybind to use in the|r |cFFFFD100Abilities|r |cFF00CCFFsection. Find the spell from the dropdown and use the|r |cFFFFD100Override Keybind|r |cFF00CCFFbox. Same can be done with trinkets under|r |cFFFFD100Gear and Items|r.\n\n2. I don't recognize this spell! What is it?\n- |cFF00CCFFIt's probably a trinket. You can press |cFFFFD100alt-shift-p|r to pause the addon and hover over the icon to see what it is!|r\n\n3. How do I disable a certain ability or trinket?\n- |cFF00CCFFHead over to |cFFFFD100Abilities|r or |cFFFFD100Gear and Items|r, find it in the dropdown list, and disable it.\n\n|r\nI made it to the bottom but I still have an issue!\n- |cFF00CCFFHead on over to|r |cFFFFD100Snapshots (Troubleshooting)|r |cFF00CCFFfor more detailed instructions."] = "Le 3 domande/problemi più comuni\n\n1. Le mie scorciatoie non vengono mostrate bene\n- |cFF00CCFFPuò succedere a volte con le macro o con le barre furtive. Puoi indicare a mano all'addon quale scorciatoia usare nella sezione|r |cFFFFD100Abilità|r|cFF00CCFF. Trova l'incantesimo nel menu a tendina e usa la casella|r |cFFFFD100Sostituisci scorciatoia|r|cFF00CCFF. Lo stesso si può fare per i ninnoli in|r |cFFFFD100Equipaggiamento e oggetti|r.\n\n2. Non riconosco questo incantesimo! Cos'è?\n- |cFF00CCFFProbabilmente è un ninnolo. Puoi premere |cFFFFD100alt-maiusc-p|r per mettere in pausa l'addon e passare il mouse sull'icona per vedere cos'è!|r\n\n3. Come disattivo una certa abilità o un certo ninnolo?\n- |cFF00CCFFVai in |cFFFFD100Abilità|r o |cFFFFD100Equipaggiamento e oggetti|r, trovalo nel menu a tendina e disattivalo.\n\n|r\nSono arrivato in fondo ma ho ancora un problema!\n- |cFF00CCFFVai su|r |cFFFFD100Istantanee (Risoluzione dei problemi)|r |cFF00CCFFper istruzioni più dettagliate.",
    ["Abilities"] = "Abilità",
    ["Edit specific abilities, such as disabling, assigning to a toggle, overriding the keybind text or icon and more."] = "Modifica abilità specifiche, per esempio disattivarle, assegnarle a un interruttore, sostituire il testo o l'icona della scorciatoia e altro.",
    ["These options apply to your selected specialization."] = "Queste opzioni valgono per la specializzazione selezionata.",
    ["Gear and Items"] = "Equipaggiamento e oggetti",
    ["Edit specific items, such as disabling, assigning to a toggle, overriding the keybind text and more."] = "Modifica oggetti specifici, per esempio disattivarli, assegnarli a un interruttore, sostituire il testo della scorciatoia e altro.",
    ["Disable Gear and Items"] = "Disattiva equipaggiamento e oggetti",
    ["If checked, no equipped trinkets, weapons, or armor with |cFF00FF00Use:|r effects will be recommended for |cFFFFD100%s|r, regardless of any other options selected below."] = "Se selezionato, non verranno consigliati ninnoli, armi o armature equipaggiati con effetti |cFF00FF00Utilizzo:|r per |cFFFFD100%s|r, indipendentemente dalle altre opzioni selezionate qui sotto.",
    ["this specialization"] = "questa specializzazione",
    ["Cooldown Manager"] = "Gestore dei cooldown",
    ["Hekili reads the Cooldown Manager to see when your buffs and debuffs are up. Turn a switch off and Hekili ignores that aura's items there. |cffffd100Gold|r: on a bar. |cff808080Grey|r: not on a bar; its switch applies when you add it."] = "Hekili legge il Gestore dei cooldown per sapere quando i tuoi potenziamenti e penalità sono attivi. Se spegni un interruttore, Hekili ignora gli elementi di quell'aura lì. |cffffd100Oro|r: su una barra. |cff808080Grigio|r: non su una barra; il suo interruttore vale quando la aggiungi.",
    ["Changes apply after combat."] = "Le modifiche si applicano dopo il combattimento.",
    ["Snapshots (Troubleshooting)"] = "Istantanee (Risoluzione dei problemi)",
    ["Learn how to report an issue with the addon, such as incorrect recommendations or bugs."] = "Scopri come segnalare un problema con l'addon, come raccomandazioni sbagliate o errori.",
    ["Snapshots"] = "Istantanee",
    ["Select a Snapshot"] = "Scegli un'Istantanea",
    ["Select a Snapshot to export."] = "Scegli un'Istantanea da esportare.",
    ["No snapshots have been generated."] = "Non è stata generata nessuna istantanea.",
    ["Take Screenshot"] = "Fai uno screenshot",
    ["If checked, the addon will take a screenshot when you manually create a snapshot.\n\nSubmitting both with your issue tickets will provide useful information for investigation purposes."] = "Se selezionato, l'addon farà uno screenshot quando crei manualmente un'istantanea.\n\nInviare entrambi con la tua segnalazione fornisce informazioni utili per le indagini.",
    ["What is a snapshot?"] = "Che cos'è un'istantanea?",
    ["Snapshots are logs of the addon's decision-making process for a set of recommendations.  If you have questions about -- or disagree with -- the addon's recommendations, reviewing a snapshot can help identify what factors led to the specific recommendations that you saw.\n\nSnapshots only capture a specific point in time, and explain the current recommendation as well as all future recommendations based on icons shown. So if you show 3 icons in the addon, the snapshot will explain the current recommendation and the next 2.\n\nYou can also freeze the addon's recommendations using the |cffffd100Pause|r binding ( |cffffd100%s|r ).  Doing so will freeze the addon's recommendations, allowing you to mouseover the display and see which conditions were met to display those recommendations.  Press Pause again to unfreeze the addon.\n\n"] = "Le istantanee sono registri del processo decisionale dell'addon per un insieme di raccomandazioni.  Se hai dubbi sulle raccomandazioni dell'addon, o non sei d'accordo, rivedere un'istantanea può aiutare a capire quali fattori hanno portato alle raccomandazioni che hai visto.\n\nLe istantanee catturano solo un momento preciso e spiegano la raccomandazione attuale e tutte quelle future in base alle icone mostrate. Quindi se nell'addon mostri 3 icone, l'istantanea spiegherà la raccomandazione attuale e le 2 successive.\n\nPuoi anche bloccare le raccomandazioni dell'addon con la scorciatoia |cffffd100Pausa|r ( |cffffd100%s|r ).  Così le raccomandazioni dell'addon si bloccano e puoi passare il mouse sul riquadro per vedere quali condizioni erano soddisfatte per mostrarle.  Premi di nuovo Pausa per sbloccare l'addon.\n\n",
    ["NOT BOUND"] = "NON ASSEGNATO",
    ["How do I get one?"] = "Come ne ottengo una?",
    ["|cFFFFD100When should I do it|r\nYou should generate the snapshot when the issue is actively happening. If you look at the recommendations and think \"this seems wrong\", that's when you should do it. Most of the time, issues can be recreated at training dummies.\n\nFor example, if the issue usually happens 20 seconds into your rotation, then an out-of-combat prepull snapshot isn't going to help the Dev or other community members diagnose and fix the issue.\n\n|cFFFFD100How do I do it|r\nYou can generate a snapshot one of 2 ways:\n• Pressing the snapshot keybind: |cffffd100%s|r\n• Pressing the pause keybind: |cffffd100%s|r\n\n|cFFFFD100Okay I made one, where is it?|r\nThe snapshot can be retrieved by picking it from dropdown list near the top of this window, then copying it from the textbox that appears. Be sure to press |cFFFFD100Ctrl + A|r before copying it so that you get the entire thing. It should be very, very long."] = "|cFFFFD100Quando farla|r\nDevi generare l'istantanea mentre il problema si sta verificando. Se guardi le raccomandazioni e pensi \"questo sembra sbagliato\", è quello il momento. Quasi sempre i problemi si possono riprodurre sui manichini d'addestramento.\n\nPer esempio, se il problema di solito si presenta 20 secondi dopo l'inizio della rotazione, un'istantanea fatta prima dell'attacco fuori dal combattimento non aiuterà lo sviluppatore o gli altri membri della comunità a capire e risolvere il problema.\n\n|cFFFFD100Come si fa|r\nPuoi generare un'istantanea in 2 modi:\n• Premendo la scorciatoia dell'istantanea: |cffffd100%s|r\n• Premendo la scorciatoia della pausa: |cffffd100%s|r\n\n|cFFFFD100Ok, l'ho fatta, dov'è?|r\nL'istantanea si recupera scegliendola dal menu a tendina in alto in questa finestra e copiandola dalla casella di testo che compare. Premi |cFFFFD100Ctrl + A|r prima di copiarla per prenderla tutta. Dovrebbe essere molto, molto lunga.",
    ["How to Submit"] = "Come inviarla",
    ["With the Snapshot Data copied to your clipboard, navigate to Pastebin."] = "Con i dati dell'istantanea copiati negli appunti, vai su Pastebin.",
    ["Paste the Snapshot Data in the large textbox ( |cFFFFD100CTRL+V|r ), then click |cFFFFD100Create New Paste|r.\n\nCopy the link address from your browser and provide it in a GitHub issue report on the Hekili Forever page."] = "Incolla i dati dell'istantanea nella casella di testo grande ( |cFFFFD100CTRL+V|r ), poi clicca |cFFFFD100Create New Paste|r.\n\nCopia l'indirizzo del link dal browser e indicalo in una segnalazione GitHub sulla pagina di Hekili Forever.",
    ["GitHub Issues"] = "Problemi su GitHub",
    ["Snapshot Data"] = "Dati dell'istantanea",
    ["Click here and press CTRL+A, CTRL+C to copy the snapshot.\n\nPaste in a text editor to review or upload to Pastebin to support an issue ticket."] = "Clicca qui e premi CTRL+A, CTRL+C per copiare l'istantanea.\n\nIncollala in un editor di testo per controllarla o caricala su Pastebin per supportare una segnalazione.",
    ["|cFF00CCFFClick the textbox above and press |cFFFFD100CTRL+A|r to select ALL text and |cFFFFD100CTRL+C|r to copy it to the clipboard.\n\nWhen pasted to a text file or Pastebin.org, the snapshot should be hundreds or thousands of lines long."] = "|cFF00CCFFClicca la casella di testo qui sopra e premi |cFFFFD100CTRL+A|r per selezionare TUTTO il testo e |cFFFFD100CTRL+C|r per copiarlo negli appunti.\n\nQuando viene incollata in un file di testo o su Pastebin.org, l'istantanea dovrebbe essere lunga centinaia o migliaia di righe.",
