    ["Ring Color"] = "Colore dell'anello",
    ["The now circle's ring when the focus ability is ready to press."] = "L'anello del cerchio \"ora\" quando l'abilità di focus è pronta da premere.",
    ["The now circle: a focus ability coming up."] = "Il cerchio \"ora\": un'abilità di focus in arrivo.",
    ["The next box and the alternatives."] = "Il riquadro \"prossima\" e le alternative.",
    ["The picks on the lane."] = "Le scelte sulla corsia.",
    ["The lane's time axis, the ruler and the focus zone."] = "L'asse del tempo della corsia, il righello e la zona di focus.",
    ["|cFFFF0000WARNING|r: This version of Hekili Forever is for a newer WoW Forever client; you should reinstall for %s."] = "|cFFFF0000ATTENZIONE|r: questa versione di Hekili Forever è per un client WoW Forever più recente; dovresti reinstallare per %s.",
}

for key, text in pairs(T) do
    rawset(L, key, text)
end
end
