GF.TR['gq_sentences'] = function()
local GQ = _G.GearQuest
if not GQ then return end

-- Hunt description sentences no shared rule covers, keyed by the exact English sentence.
if GQ.ActiveLocale ~= "itIT" then
    return
end

local sentences = GQ.LocaleSentences
for k, v in pairs({
    ["Binds when picked up."] = "Si lega quando raccolto.",
    ["Leather wrist, 15 armor — more than the Classic grey bracers in this band."] = "Polsi di cuoio, 15 di armatura — più dei bracciali grigi di Classic in questa fascia.",
    ["Leather wrist, 15 armor."] = "Polsi di cuoio, 15 di armatura.",
    ["Costs Honor Points and tokens (Marks of Honor)."] = "Costa Punti Onore e gettoni (Marchi d'Onore).",
    ["The seller is not listed on Wowhead yet."] = "Il venditore non è ancora elencato su Wowhead.",
    ["+13 Fire damage is the Destruction off-school."] = "+13 danni da Fuoco è la scuola secondaria della Distruzione.",
    ["+13 Frost damage also scores for Arcane."] = "+13 danni da Gelo contano anche per Arcano.",
    ["(4) Melee attacks from behind have a 5% chance to bleed the target for 68 to 83 damage over 5 sec."] = "(4) Gli attacchi in mischia alle spalle hanno il 5% di probabilità di far sanguinare il bersaglio per 68-83 danni in 5 sec.",
    ["Checked for Combat, Assassination and Subtlety."] = "Verificato per Combattimento, Assassinio e Scaltrezza.",
    ["The legs are a hunt at 14 and 15, and the boots at 15 and 16, until the Fang pieces take those slots."] = "Le gambe sono una caccia a 14 e 15, e gli stivali a 15 e 16, finché i pezzi della Zanna non occupano quegli slot.",
    ["The chest, gloves and belt stay behind stronger leather even with all five pieces."] = "Torace, guanti e cintura restano dietro al cuoio più forte anche con tutti e cinque i pezzi.",
    ["(4) At 25% health, restore 100 health and mana over 5 sec, once every 5 min."] = "(4) Al 25% di salute, ripristina 100 salute e mana in 5 sec, una volta ogni 5 min.",
    ["(5) Melee attacks can inflict Dream Venom and stun for 1 sec."] = "(5) Gli attacchi in mischia possono infliggere Dream Venom e stordire per 1 sec.",
    ["Beast Mastery and Marksmanship: the legs, feet, belt, and gloves are the hunt from 18 through about 24."] = "Padronanza delle Bestie e Precisione: gambe, piedi, cintura e guanti sono la caccia dal 18 fino a circa il 24.",
    ["Armor of the Fang is not, because those specs barely count melee damage and the chest has no agility."] = "Armor of the Fang non lo è, perché quelle spec contano a malapena il danno in mischia e il torace non ha agilità.",
    ["Survival keeps all five through 23, and at 24 the legs are what remain."] = "Sopravvivenza tiene tutti e cinque fino al 23, e al 24 restano le gambe.",
    ["Survival wants all 5 for Dream Venom."] = "Sopravvivenza vuole tutti e 5 per Dream Venom.",
    ["The belt becomes BiS with the set."] = "La cintura diventa BiS con il set.",
    ["Gloves are a hunt from 14 on their own, and the legs from 17."] = "I guanti sono una caccia dal 14 da soli, e le gambe dal 17.",
    ["A druid in all five turns into a serpent."] = "Un druido con tutti e cinque i pezzi si trasforma in un serpente.",
    ["The color follows your race, and Prowl or Stealth slithers."] = "Il colore segue la tua razza, e Prowl o Stealth striscia.",
    ["Combat, Assassination and Subtlety: all five pieces are BiS together from 18 through 23."] = "Combattimento, Assassinio e Scaltrezza: tutti e cinque i pezzi sono BiS insieme dal 18 al 23.",
    ["The chest and the belt become BiS with the set."] = "Il torace e la cintura diventano BiS con il set.",
    ["Enhancement: all five pieces are BiS together from 18 through 28."] = "Potenziamento: tutti e cinque i pezzi sono BiS insieme dal 18 al 28.",
    ["At 29 the chest falls off and the other four remain."] = "Al 29 il torace cade e restano gli altri quattro.",
    ["The 2-piece intellect is a large part of why the set lasts into the high 20s."] = "L'intelletto dei 2 pezzi è gran parte del motivo per cui il set dura fino ai 20 alti.",
    ["Feral: all five pieces are BiS together from 18 through 23."] = "Ferino: tutti e cinque i pezzi sono BiS insieme dal 18 al 23.",
    ["The legs and gloves are strong before the set is finished."] = "Le gambe e i guanti sono forti prima che il set sia completo.",
    ["The chest becomes BiS with the set."] = "Il torace diventa BiS con il set.",
    ["Wearing all five pieces transforms you into a serpent."] = "Indossare tutti e cinque i pezzi ti trasforma in un serpente.",
    ["The color depends on your race, and Prowl or Stealth uses a unique slithering animation."] = "Il colore dipende dalla tua razza, e Prowl o Stealth usa un'animazione strisciante unica.",
    ["Smite."] = "Smite.",
    ["Rotheap Inards are party loot at 100%."] = "Rotheap Inards sono bottino di gruppo al 100%.",
    ["Turn them in to Rethiel the Greenwarden."] = "Consegnali a Rethiel the Greenwarden.",
    ["You also need to have obtained the Sulfuron Hammer."] = "Devi anche aver ottenuto il Sulfuron Hammer.",
    ["(4) When mana falls below 15%, restore 200 mana over 10 sec, once every 5 min."] = "(4) Quando il mana scende sotto il 15%, ripristina 200 mana in 10 sec, una volta ogni 5 min.",
    ["Twice as much mana in Haunted and Wasteland."] = "Il doppio del mana in Haunted e Wasteland.",
    ["(5) Healing spells can heal for an additional 40 every 3 sec for 15 sec."] = "(5) Gli incantesimi di guarigione possono curare di ulteriori 40 ogni 3 sec per 15 sec.",
    ["Holy and Discipline: at 18 the chest, sash, gloves, and leggings are the hunt."] = "Sacro e Disciplina: al 18 torace, fascia, guanti e gambali sono la caccia.",
    ["At 19 all five pieces are together."] = "Al 19 tutti e cinque i pezzi sono insieme.",
    ["From 20 the leggings fall off."] = "Dal 20 i gambali cadono.",
    ["The chest, sash, and gloves stay through 21, and the treads stay in the top 3 into the high 20s."] = "Torace, fascia e guanti restano fino al 21, e i calzari restano nei primi 3 fino ai 20 alti.",
    ["Holy: the treads are a hunt from 19 through 29."] = "Sacro: i calzari sono una caccia dal 19 al 29.",
    ["The other four pieces do not beat mail and plate, even with the set."] = "Gli altri quattro pezzi non battono maglia e piastre, nemmeno con il set.",
    ["Restoration: all five pieces are the hunt together at 19."] = "Rinnovamento: tutti e cinque i pezzi sono la caccia insieme al 19.",
    ["On Horde the chest, sash, and gloves stay through 21."] = "Per l'Orda torace, fascia e guanti restano fino al 21.",
    ["The treads stay in the top 3 through about 29."] = "I calzari restano nei primi 3 fino a circa il 29.",
    ["(4) Taking damage can grant Enraging Light for 10 sec, adding 20 Holy to each melee attack, 60 against Undead."] = "(4) Subire danni può concedere Enraging Light per 10 sec, aggiungendo 20 Sacro a ogni attacco in mischia, 60 contro i Non Morti.",
    ["(5) +1% hit."] = "(5) +1% colpire.",
    ["(6) At 20% health, absorb 480 damage for 10 sec, once every 4 min."] = "(6) Al 20% di salute, assorbe 480 danni per 10 sec, una volta ogni 4 min.",
    ["For Arms and Fury, the belt is a hunt from 32 to 39, the chest from 34 to 39, and the legs at 39."] = "Per Armi e Furia, la cintura è una caccia dal 32 al 39, il torace dal 34 al 39 e le gambe al 39.",
    ["The gauntlets sit in the top 3 around 33 to 34."] = "Le manopole stanno nei primi 3 intorno al 33-34.",
    ["For Protection, the boots are a hunt from 30 to 36, the bracers from 31 to 35, and the chest from 34 to 39."] = "Per Protezione, gli stivali sono una caccia dal 30 al 36, i bracciali dal 31 al 35 e il torace dal 34 al 39.",
    ["For Retribution, the belt is a hunt from 32 to 36, the chest from 34 to 39, and the legs at 39."] = "Per Castigo, la cintura è una caccia dal 32 al 36, il torace dal 34 al 39 e le gambe al 39.",
    ["The gauntlets sit in the top 3 at 33 and 34."] = "Le manopole stanno nei primi 3 al 33 e 34.",
    ["Shredder."] = "Shredder.",
    ["Druid only."] = "Solo druidi.",
    ["To make him spawn, use the Beastly Effigy in bear form: cast Enrage, then Challenging Roar."] = "Per farlo comparire, usa il Beastly Effigy in forma d'orso: lancia Enrage, poi Challenging Roar.",
    ["Part of the Chain of the Scarlet Crusade."] = "Parte della catena della Scarlet Crusade.",
    ["The drop is very rare."] = "Il bottino è molto raro.",
    ["Fished up."] = "Pescato.",
    ["Ultra-rare, with no confirmed pool."] = "Ultra-raro, senza gruppo di bottino confermato.",
    ["Found inside another item."] = "Si trova dentro un altro oggetto.",
    ["Indexed from Wowhead Forever."] = "Indicizzato da Wowhead Forever.",
    ["Source not listed yet."] = "Fonte non ancora elencata.",
    ["Druid idol: shapeshifting costs 40 less mana."] = "Idolo del druido: cambiare forma costa 40 mana in meno.",
    ["Bear and Balance have no Classic idol until 60."] = "Orso ed Equilibrio non hanno un idolo Classic fino al 60.",
    ["Fills the relic slot until the Classic idols (52+)."] = "Occupa lo slot reliquia fino agli idoli Classic (52+).",
    ["Restoration's first Classic idol is 57."] = "Il primo idolo Classic di Rinnovamento è al 57.",
    ["Leather chest, 41 armor — more than the Classic grey vests in this band."] = "Torace di cuoio, 41 di armatura — più dei panciotti grigi di Classic in questa fascia.",
    ["Leather chest, 41 armor."] = "Torace di cuoio, 41 di armatura.",
    ["Mail legs, 71 armor."] = "Gambe di maglia, 71 di armatura.",
    ["Burnt Leather Breeches take over at 5."] = "Burnt Leather Breeches subentrano al 5.",
    ["Shaman totem: Lightning Bolt costs 5 less mana."] = "Totem dello sciamano: Lightning Bolt costa 5 mana in meno.",
    ["Fills the relic slot until Totem of Rage (52)."] = "Occupa lo slot reliquia fino al Totem of Rage (52).",
    ["Mail chest, 67 armor."] = "Torace di maglia, 67 di armatura.",
    ["+stat leather vests take over at 5."] = "I panciotti di cuoio con statistiche subentrano al 5.",
    ["Mail feet, 46 armor — beats the Classic 1–9 leather greys on armor alone."] = "Piedi di maglia, 46 di armatura — battono i grigi di cuoio Classic 1–9 solo per armatura.",
    ["Mail waist, 38 armor — more armor than the Classic grey/white belts in this band."] = "Vita di maglia, 38 di armatura — più armatura delle cinture grigie/bianche di Classic in questa fascia.",
    ["Quest reward."] = "Ricompensa di missione.",
    ["Alliance: collect the Head of the Baron in the Ruins of Lordaeron and bring it to Captain Truman."] = "Alleanza: raccogli la Head of the Baron nelle Rovine di Lordaeron e portala al Capitano Truman.",
    ["Horde: report to Master Apothecary Faranell in Undercity."] = "Orda: presentati al Master Apothecary Faranell a Undercity.",
    ["One of the reward choices."] = "Una delle ricompense tra cui scegliere.",
    ["Reward from Abominable Creatures (Alliance) or Unending Torment (Horde)."] = "Ricompensa da Abominable Creatures (Alleanza) o Unending Torment (Orda).",
    ["ProgressStep right up, step right up! &nbsp;If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so! &nbsp;You can redeem tickets in various denominations for wondrous and fantastic prizes. &nbsp;Don't be shy, give it a try!"] = "Avanti, avanti, fatevi avanti! Se avete biglietti della Fiera di Darkmoon da riscattare, ditelo pure! Potete riscattare biglietti di vari tagli per premi meravigliosi e fantastici. Non siate timidi, provate!",
    ["Pick it over the other reward choices."] = "Sceglilo al posto delle altre ricompense.",
    ["The reward is mailed to you after you finish the quest."] = "La ricompensa ti viene spedita per posta dopo aver finito la missione.",
    ["ProgressAvast Lubber! &nbsp; Bring me 12 trinkets of the Arena Master and then ye shall be a Grandmaster of the Gurubashi Arena! &nbsp; Arrrr!"] = "Ohé, marinaio d'acqua dolce! Portami 12 gingilli dell'Arena Master e sarai un Gran Maestro dell'Arena dei Gurubashi! Arrrr!",
    ["ProgressIf you bring me thirty necrotic runes, I will give you your choice of hand protection in return."] = "Se mi porti trenta rune necrotiche, ti darò in cambio la protezione per le mani che preferisci.",
    ["These should prove valuable in our fight against the undead Scourge."] = "Dovrebbero rivelarsi preziose nella nostra lotta contro la Piaga non morta.",
    ["War comes, &lt;name&gt;, and with it comes untold horrors."] = "La guerra arriva, <name>, e con essa orrori indicibili.",
    ["You have done all that could be asked of you and for that you should be rewarded.Should this... this prophecy ever come to pass...The future of us all could be at an end.These armaments will prove invaluable to your campaign in this desert."] = "Hai fatto tutto ciò che si poteva chiedere e per questo meriti una ricompensa.Se questa... questa profezia dovesse mai avverarsi...Il futuro di tutti noi potrebbe finire.Queste armi si riveleranno preziosissime per la tua campagna in questo deserto.",
    ["Your garment is ready! &nbsp;And that silk you gathered was so nice... you don't mind if I made it a little short so that I'd have some silk left over for me, do you?I'm only joking. &nbsp;It'll fit you great, and will be perfect for both adventure and formal dining. &nbsp;Enjoy!"] = "Il tuo indumento è pronto! E quella seta che hai raccolto era così bella... non ti dispiace se l'ho fatto un po' corto per avanzarne un po' per me, vero?Scherzo, scherzo. Ti starà benissimo, e sarà perfetto sia per l'avventura sia per le cene eleganti. Goditelo!",
    ["Thank you, &lt;name&gt;. &nbsp;These gauntlets are my best work. &nbsp;Take them."] = "Grazie, <name>. Questi guanti d'arme sono il mio lavoro migliore. Prendili.",
    ["In wearing them, you bring honor to me and my ancestors."] = "Indossandoli, porti onore a me e ai miei antenati.",
    ["I am sure you endured much hardship and shed much blood on my task, &lt;name&gt;. &nbsp;Here is the product of your toil.May you wear it well, and may you one day return here with stories of its service to you."] = "Sono sicuro che hai sopportato molte difficoltà e versato molto sangue per il mio compito, <name>. Ecco il frutto della tua fatica.Che tu possa indossarlo bene, e che un giorno tu possa tornare qui con storie del suo servizio.",
    ["I give this helm to you.Great deeds brought you to me, &lt;name&gt;, and Earthmother willing... even greater deeds lie before you."] = "Ti do questo elmo.Grandi imprese ti hanno portato da me, <name>, e se la Madre Terra vuole... imprese ancora più grandi ti attendono.",
    ["A quest."] = "Una missione.",
    ["Always up to date."] = "Sempre aggiornato.",
    ["Here are your legguards, &lt;name&gt;. &nbsp;Let me know how they fit or if you need any modifications. &nbsp;I aim to please! &nbsp;At least I used to.These days I don't care much for my craft. &nbsp;But it beats being a mindless minion of the Scourge!I guess."] = "Ecco i tuoi gambali, <name>. Fammi sapere come ti stanno o se servono modifiche. Mi piace accontentare! O almeno una volta era così.Oggi non mi importa molto del mio mestiere. Ma è meglio che essere un servo senza cervello della Piaga!Immagino.",
    ["You should be proud of yourself, &lt;name&gt;. &nbsp;Many mages have fallen to the creatures you faced.The Celestial Orb is ready. &nbsp;Or if you'd like I can mount it atop a staff. &nbsp;It's up to you. &nbsp;I'd prefer the orb, but who am I to judge?"] = "Dovresti essere fiero di te, <name>. Molti maghi sono caduti contro le creature che hai affrontato.La Celestial Orb è pronta. Oppure, se vuoi, posso montarla in cima a un bastone. Sta a te. Io preferirei la sfera, ma chi sono io per giudicare?",
    ["The Final Tablets are in Blackrock Spire."] = "Le Final Tablets sono a Blackrock Spire.",
    ["ProgressSo many slain."] = "Quanti caduti.",
    ["Blood drenches the fields."] = "Il sangue inzuppa i campi.",
    ["Yet..."] = "Eppure...",
    ["You live..."] = "Sei vivo...",
    ["You have persevered."] = "Hai perseverato.",
    ["You have led our armies to many victories."] = "Hai guidato i nostri eserciti a molte vittorie.",
    ["For this, then, soldier, you have earned a new rank.Present your insignia."] = "Per questo, soldato, hai guadagnato un nuovo grado.Mostra le tue insegne.",
    ["ProgressHow be that talisman, mon?"] = "Come sta quel talismano, mon?",
    ["It look like it be time to add a little more magic and mojo to its leaves."] = "Sembra che sia ora di aggiungere un po' più di magia e mojo alle sue foglie.",
    ["It need a little bloom in its wilt."] = "Ha bisogno di un po' di fioritura nel suo appassire.",
    ["Give it here and Maywiki fix it right up."] = "Dallo qui e Maywiki lo sistema subito.",
    ["Sulhasa in southern Barrens wants you to clear out 7 Stormhide lizards and 7 Hecklefang Stalkers in the area so she can leave the tree safely."] = "Sulhasa, nel Barrens meridionale, vuole che tu elimini 7 lucertole Stormhide e 7 Hecklefang Stalkers nella zona così può lasciare l'albero in sicurezza.",
    ["Reward from the quest 'Final Passage', the last of ten steps."] = "Ricompensa della missione 'Final Passage', l'ultima di dieci passaggi.",
    ["Bring Beginnings of the Undead Threat out of Scarlet Monastery Library."] = "Porta Beginnings of the Undead Threat fuori dalla Biblioteca del Monastero Scarlatto.",
    ["Pick the hammer over the other reward."] = "Scegli il martello al posto dell'altra ricompensa.",
    ["Pick the wand over the other reward."] = "Scegli la bacchetta al posto dell'altra ricompensa.",
    ["This quest is offered after you turn in 10 library books to Garion Wendell in Stormwind or Owen Thadd in Undercity."] = "Questa missione viene offerta dopo aver consegnato 10 libri della biblioteca a Garion Wendell a Stormwind o a Owen Thadd a Undercity.",
    ["Here's your armor, &lt;name&gt;. &nbsp;This will stand up to the strongest assaults or my name isn't Furen Longbeard!And I have to thank you. &nbsp;I learned a lot while working with the materials you brought me. &nbsp;I think I'll have another breakthrough one day!I'm going to send what I learned to other blacksmiths of the Alliance.I'll tell them you were a big help, and maybe they'll want to return the favor."] = "Ecco la tua armatura, <name>. Resisterà ai colpi più forti o non mi chiamo Furen Longbeard!E devo ringraziarti. Ho imparato molto lavorando con i materiali che mi hai portato. Credo che un giorno farò un'altra scoperta!Manderò ciò che ho imparato agli altri fabbri dell'Alleanza.Dirò loro che sei stato di grande aiuto, e forse vorranno ricambiare il favore.",
    ["This quest is offered after you turn in 20 library books to Garion Wendell in Stormwind or Owen Thadd in Undercity."] = "Questa missione viene offerta dopo aver consegnato 20 libri della biblioteca a Garion Wendell a Stormwind o a Owen Thadd a Undercity.",
    ["Here are some weapons, hot off the anvil and made with the new umbral ore you brought me!Please, &lt;name&gt;, take your pick!"] = "Ecco alcune armi, appena uscite dall'incudine e fatte con il nuovo minerale umbrale che mi hai portato!Ti prego, <name>, scegli quella che preferisci!",
    ["A level 10 Quest."] = "Una missione di livello 10.",
    ["I can barely believe it! &nbsp;Furen's technique was a success, and this armor should withstand tremendous levels of stress.Here you are, &lt;name&gt;. &nbsp;And thank you. &nbsp;I wouldn't have believed Furen's discovery if you hadn't gathered the materials I needed to test it myself."] = "Non riesco quasi a crederci! La tecnica di Furen ha funzionato, e questa armatura dovrebbe resistere a sollecitazioni enormi.Ecco a te, <name>. E grazie. Non avrei creduto alla scoperta di Furen se tu non avessi raccolto i materiali che mi servivano per provarla di persona.",
    ["I will keep three of the weapons you returned to me, as mementos of my pain and loss. &nbsp;But please, &lt;name&gt;, choose your favorite of the heirlooms and keep it for yourself.May it serve you greater than it served its cursed, former owners."] = "Terrò tre delle armi che mi hai riportato, come ricordo del mio dolore e della mia perdita. Ma ti prego, <name>, scegli la tua preferita tra le eredità e tienila per te.Che ti serva meglio di quanto abbia servito i suoi maledetti ex proprietari.",
    ["As a hero of the Stormpike, you may choose one item from these recently plun... er, recovered treasures."] = "Come eroe degli Stormpike, puoi scegliere un oggetto tra questi tesori recentemente saccheggia... ehm, recuperati.",
    ["ProgressIt is good to see you again, &lt;class&gt;."] = "È bello rivederti, <class>.",
    ["I had not expected you to return."] = "Non mi aspettavo che tornassi.",
    ["Alas, you have proven yourself a brave and honorable soldier of the Frostwolf.Your time has come again, &lt;name&gt;."] = "Ahimè, ti sei dimostrato un soldato coraggioso e onorevole dei Frostwolf.Il tuo momento è arrivato di nuovo, <name>.",
    ["You have earned a new ranking and as such, a new insignia denoting this rise in stature.Present your insignia."] = "Hai guadagnato un nuovo grado e, di conseguenza, una nuova insegna che indica questa ascesa.Mostra la tua insegna.",
    ["ProgressThe base buzzes with news of your exploits in the Field of Strife!"] = "La base è in fermento per le notizie delle tue imprese nel Field of Strife!",
    ["You have struck mighty blows against our enemy - crushing their morale!"] = "Hai sferrato colpi possenti al nostro nemico, distruggendone il morale!",
    ["For this, you have earned a rank of honor among the Stormpike.Present your insignia."] = "Per questo hai guadagnato un grado d'onore tra gli Stormpike.Mostra la tua insegna.",
    ["Alliance only."] = "Solo Alleanza.",
    ["Accept this talisman, &lt;class&gt;."] = "Accetta questo talismano, <class>.",
    ["Accept it and use its power to strike down our mutual enemies.Know that around your neck you carry a piece of history."] = "Accettalo e usa il suo potere per abbattere i nostri nemici comuni.Sappi che al collo porti un pezzo di storia.",
    ["Kezan was once a grand territory of the Zandalar Empire."] = "Kezan era un tempo un grande territorio dell'Impero Zandalar.",
    ["Alas, the taint of goblin trade princes would force out my proud brothers and sisters.Kezan is now home to the goblin capital of the Undermine; but know that before the taint, it held greatness."] = "Ahimè, la corruzione dei principi mercanti goblin costrinse i miei orgogliosi fratelli e sorelle ad andarsene.Kezan è ora la casa della capitale goblin di Undermine; ma sappi che prima di quella corruzione possedeva grandezza.",
    ["Still to this day Kezan is considered sacred land to my people."] = "Ancora oggi Kezan è considerata terra sacra dal mio popolo.",
    ["ProgressCall forth your demons, &lt;class&gt;."] = "Evoca i tuoi demoni, <class>.",
    ["Let them bask in the energy of Kezan's Taint."] = "Lascia che si crogiolino nell'energia della Kezan's Taint.",
    ["Command them on the field of battle!"] = "Comandali sul campo di battaglia!",
    ["Decimate the enemy!Yes..."] = "Decima il nemico!Sì...",
    ["The time has come to apply the final enhancement to Kezan's Taint."] = "È giunto il momento di applicare il potenziamento finale a Kezan's Taint.",
    ["Give me the talisman."] = "Dammi il talismano.",
    ["Here's your armor, &lt;name&gt;. &nbsp;Furen's process worked brilliantly! &nbsp;Perfectly! &nbsp;Marvelously, truly!You could run this armor over with a siege engine and it would spring right back into shape!"] = "Ecco la tua armatura, <name>. Il procedimento di Furen ha funzionato alla grande! Perfettamente! Meravigliosamente, davvero!Potresti passarci sopra con una macchina d'assedio e tornerebbe subito in forma!",
    ["ProgressBefore me stands an exalted hero of the Alliance.&lt;Lieutenant Haggerdin salutes.&gt;Few have earned such a rank among the Stormpike."] = "Davanti a me sta un eroe esaltato dell'Alleanza.<Il Tenente Haggerdin saluta.>Pochi hanno guadagnato un tale grado tra gli Stormpike.",
    ["I have watched the enemy fall before you."] = "Ho visto il nemico cadere davanti a te.",
    ["I have seen their resolve crumble in your presence."] = "Ho visto la loro determinazione sgretolarsi in tua presenza.",
    ["When you enter the fray, you become the beacon of hope for our forces!Present your insignia."] = "Quando entri nella mischia, diventi il faro di speranza per le nostre forze!Mostra la tua insegna.",
    ["ProgressAn extremely sturdy cabinet stands before you, securely fastened shut by a built-in lock. &nbsp;The front of the cabinet is deeply scratched and marked. &nbsp;This could be surmised as being from numerous and violent failed attempts to reveal whatever secrets the cabinet currently obfuscates from view.If you are going to open this cabinet, you will need to find the key."] = "Davanti a te c'è un armadietto estremamente robusto, saldamente chiuso da una serratura incorporata. Il fronte dell'armadietto è profondamente graffiato e segnato. Si può supporre che derivi da numerosi e violenti tentativi falliti di rivelare i segreti che l'armadietto nasconde alla vista.Se vuoi aprire questo armadietto, dovrai trovare la chiave.",
    ["ProgressMolthor delivers word from King Rastakhan, &lt;name&gt;."] = "Molthor porta un messaggio da parte di Re Rastakhan, <name>.",
    ["The royal court is most impressed with your decimation of the Hakkari forces."] = "La corte reale è molto colpita dalla tua decimazione delle forze degli Hakkari.",
    ["I am to award you with the final weave in your talisman."] = "Devo conferirti l'ultima trama del tuo talismano.",
    ["Hand it to me."] = "Consegnamelo.",
    ["Rituals of Power sends you into Scarlet Monastery Library."] = "Rituals of Power ti manda nella Biblioteca del Monastero Scarlatto.",
    ["Bring Bink her Mage-tastic Gizmonitor."] = "Porta a Bink il suo Mage-tastic Gizmonitor.",
    ["Here is your robe. &nbsp;It's one of my best made yet! &nbsp;Wear it with pride, and when people ask... tell them you got it at the Larson Clothiers!"] = "Ecco la tua veste. È una delle mie migliori! Indossala con orgoglio e, quando la gente ti chiederà... dì che l'hai presa da Larson Clothiers!",
    ["I have finished with your piece of armor, and I am quite pleased. &nbsp;Furen's new techniques meshed perfectly with my own and I am sure this armor will prove to be quite resilient.Thank you, &lt;name&gt;. &nbsp;And may this serve you well in future battles."] = "Ho finito il tuo pezzo di armatura e ne sono molto soddisfatto. Le nuove tecniche di Furen si sono fuse perfettamente con le mie e sono sicuro che questa armatura si rivelerà molto resistente.Grazie, <name>. E che ti serva bene nelle battaglie future.",
    ["&lt;name&gt;, your successful re-engineering of the cauldrons is a tremendous victory for us!Let all within my presence hear: for service to the Forsaken and to the Horde as a whole above and beyond what was expected - in the face of overwhelming odds and incredible danger, might I add - I give &lt;name&gt; this, and I extend upon him our undying gratitude as a true hero of the Horde. &nbsp;Huzzah!"] = "<name>, la tua riuscita riprogettazione dei calderoni è una vittoria enorme per noi!Che tutti i presenti ascoltino: per il servizio reso ai Reietti e all'Orda intera, ben oltre quanto ci si aspettasse — di fronte a probabilità schiaccianti e a un pericolo incredibile, se mi è permesso aggiungere — dono a <name> questo, ed estendo a lui la nostra eterna gratitudine come vero eroe dell'Orda. Urrà!",
    ["Here is your nether-lace, &lt;name&gt;. &nbsp;It is both comfortable and durable, and holds the magic of the laughing sisters' hair.Enjoy, and if you find it amenable, please mention so to Deino. &nbsp;She is a &lt;class&gt; on whose good side I wish to stay..."] = "Ecco il tuo nether-lace, <name>. È comodo e resistente, e custodisce la magia dei capelli delle sorelle ridenti.Goditelo e, se lo trovi gradevole, ti prego di dirlo a Deino. È una <class> con la quale desidero restare in buoni rapporti...",
    ["Now isn't this interesting?"] = "Non è interessante?",
    ["You say you found this tablet on a small, deserted island at The Overlook Cliffs in The Hinterlands, &lt;class&gt;?"] = "Dici di aver trovato questa tavoletta su una piccola isola deserta a The Overlook Cliffs negli Hinterlands, <class>?",
    ["Very interesting indeed."] = "Davvero molto interessante.",
    ["I thank you for your efforts in this matter."] = "Ti ringrazio per i tuoi sforzi in questa faccenda.",
    ["Our Dark Lady shall be very pleased with this discovery."] = "La nostra Signora Oscura sarà molto lieta di questa scoperta.",
    ["Here, allow me to reward you proportionately."] = "Ecco, lascia che ti ricompensi in modo proporzionato.",
    ["Erlgadin in Stranglethorn Vale."] = "Erlgadin a Stranglethorn Vale.",
    ["Progress*Whir* *Click* &nbsp;I seek rare fish for Fishmaster Bluegill to catalogue. &nbsp; If you bring me a Keefer's Angelfish, I will provide you with this fine reward. *Zzzap* *Whir*."] = "*Whir* *Click* Cerco pesci rari da catalogare per Fishmaster Bluegill. Se mi porti un Keefer's Angelfish, ti darò questa bella ricompensa. *Zzzap* *Whir*.",
    ["Find what awaits you."] = "Trova ciò che ti attende.",
    ["It will take time for our scholars to study the pendant you brought us. &nbsp;But for your service to the Horde I would like to offer you a small token.Thank you, &lt;name&gt;. &nbsp;Your acts bring honor to you, and to us."] = "Ci vorrà tempo prima che i nostri studiosi studino il pendente che ci hai portato. Ma per il tuo servizio all'Orda vorrei offrirti un piccolo pegno.Grazie, <name>. Le tue azioni portano onore a te e a noi.",
    ["Return the monogrammed silver hair clip to its owner."] = "Restituisci il fermaglio d'argento con monogramma al suo proprietario.",
    ["Here are your robes, &lt;name&gt;. &nbsp;Wear them well."] = "Ecco le tue vesti, <name>. Indossale bene.",
    ["ProgressIt is good to see you in good health, &lt;name&gt;."] = "È bello vederti in buona salute, <name>.",
    ["The glorious battles you have undertaken affect all life on this planet."] = "Le gloriose battaglie che hai intrapreso influenzano ogni forma di vita su questo pianeta.",
    ["Hakkar must never leave the confines of Zul'Gurub as the world will surely collapse beneath his immense hunger.Give me your talisman and I shall amplify its strength."] = "Hakkar non deve mai lasciare i confini di Zul'Gurub, altrimenti il mondo crollerà di certo sotto la sua immensa fame.Dammi il tuo talismano e ne amplificherò la forza.",
    ["Use the Strength of Mugamba to punish our enemies!"] = "Usa la Strength of Mugamba per punire i nostri nemici!",
    ["ProgressDrek'Thar sings your praises."] = "Drek'Thar canta le tue lodi.",
    ["Kalimdor is abuzz with tales of your heroics."] = "Kalimdor è in fermento per i racconti delle tue gesta.",
    ["The Warchief glows - your stalwart defense of our clan has pleased him greatly.You have earned the Eye of Command.Present your insignia, Commander &lt;name&gt;."] = "Il Capoguerra risplende: la tua strenua difesa del nostro clan lo ha reso molto felice.Hai guadagnato l'Eye of Command.Mostra la tua insegna, Comandante <name>.",
    ["ProgressTales of your battles against the Gurubashi are whispered in the winds, &lt;class&gt;."] = "I racconti delle tue battaglie contro i Gurubashi sussurrano nei venti, <class>.",
    ["Even royalty is beginning to talk of your deeds."] = "Perfino i reali cominciano a parlare delle tue imprese.",
    ["It is rumored that King Rastakhan even mentioned you by name.The time has come to imbue the Eye."] = "Si dice che Re Rastakhan ti abbia perfino citato per nome.È giunto il momento di infondere l'Eye.",
    ["Hand me the talisman and I shall perform the service."] = "Dammi il talismano e compirò il rito.",
    ["ProgressNever have I seen such tenacity!"] = "Non ho mai visto una tale tenacia!",
    ["The Bronze Flight grants you one final enchantment."] = "Il Bronze Flight ti concede un ultimo incantamento.",
    ["The Timeless One himself has requested it so!Hand me your signet ring so that I may make the necessary adjustments."] = "Lo ha chiesto il Timeless One in persona!Dammi il tuo anello con sigillo così posso fare gli aggiustamenti necessari.",
    ["Know this, heathen: A catastrophe has brought us together."] = "Sappi questo, infedele: una catastrofe ci ha riuniti.",
    ["Your pagan ways are neither understood nor appreciated by Zandalar but we are a fair people."] = "I tuoi usi pagani non sono né compresi né apprezzati da Zandalar, ma siamo un popolo giusto.",
    ["Wear this brand around your neck."] = "Porta questo marchio al collo.",
    ["It shall serve as both a warning to our enemies and a symbol of your friendship to Zandalar.Continue to serve our people and I will amplify the power of the brand."] = "Servirà sia da avvertimento per i nostri nemici sia da simbolo della tua amicizia con Zandalar.Continua a servire il nostro popolo e amplificherò il potere del marchio.",
    ["&lt;name&gt;, you have slain all three beasts that comprise the Ashenvale Hunt. &nbsp;You have brought me adequate proof of their demise; there is no question of your strength and tenacity. &nbsp;The blood of a hunter streaks through your veins, and you should be commended!Please, accept this bauble as a sign of congratulations on your mighty deeds done in Ashenvale for the Horde today. &nbsp;May your ancestors watch over you!"] = "<name>, hai ucciso tutte e tre le bestie che compongono la Ashenvale Hunt. Mi hai portato prove adeguate della loro morte; non c'è dubbio sulla tua forza e tenacia. Il sangue di un cacciatore scorre nelle tue vene, e meriti un elogio!Ti prego, accetta questo ninnolo come segno di congratulazioni per le tue possenti imprese compiute oggi ad Ashenvale per l'Orda. Che i tuoi antenati veglino su di te!",
    ["ProgressAh, &lt;name&gt;, it is good to smell you again.You'll have to excuse my sense of humor."] = "Ah, <name>, è bello sentire di nuovo il tuo odore.Dovrai scusare il mio senso dell'umorismo.",
    ["It can be most foul at times.I sense that you have caused great anguish to our enemies."] = "A volte può essere molto sgradevole.Sento che hai causato grande angoscia ai nostri nemici.",
    ["The forces of Hakkar cry out your name in anger."] = "Le forze di Hakkar gridano il tuo nome con rabbia.",
    ["This is most excellent.You have earned another weave on your talisman."] = "Ottimo.Hai guadagnato un'altra trama sul tuo talismano.",
    ["ProgressKing Rastakhan sends his regards, Master &lt;name&gt;."] = "Re Rastakhan ti manda i suoi saluti, Maestro <name>.",
    ["Such an honor has never been given to one outside the Zandalar tribe.Give me your talisman so that I may enhance it once more."] = "Un tale onore non è mai stato concesso a qualcuno al di fuori della tribù Zandalar.Dammi il tuo talismano così posso potenziarlo ancora una volta.",
    ["Know that the Rage of Mugamba is now intrinsically connected to your very soul."] = "Sappi che la Rage of Mugamba è ora intrinsecamente legata alla tua stessa anima.",
    ["Greetings, champion."] = "Salve, campione.",
    ["I am Jonathan, keeper of the sacred gong and eternal watcher of the Bronze Flight.I have been empowered by the Timeless One himself to grant you an item of your choosing from his timeless treasure trove."] = "Sono Jonathan, custode del sacro gong e osservatore eterno del Bronze Flight.Il Timeless One in persona mi ha dato il potere di concederti un oggetto a tua scelta dal suo tesoro senza tempo.",
    ["May it aid you in your battles against C'Thun."] = "Che ti aiuti nelle tue battaglie contro C'Thun.",
    ["Help Walton survive the encounter with Terry Longdrink and the Kul Tiras marines."] = "Aiuta Walton a sopravvivere all'incontro con Terry Longdrink e i marine di Kul Tiras.",
    ["Deathstalker Masoj needs you to place the three Apothecary Vials on peaks around Hillsbrad Foothills and return to him."] = "Deathstalker Masoj ha bisogno che tu collochi le tre Apothecary Vials sulle cime attorno alle Colline di Hillsbrad e poi torni da lui.",
    ["ProgressSha-mon!"] = "Sha-mon!",
    ["Maywiki make a joke!&lt;Maywiki laughs.&gt;So, you been using the spirits and elements against our enemies in Zul'Gurub, eh?"] = "Maywiki fa una battuta!<Maywiki ride.>Allora, hai usato gli spiriti e gli elementi contro i nostri nemici a Zul'Gurub, eh?",
    ["Spirits be praised!Maywiki gonna brighten your orb."] = "Siano lodati gli spiriti!Maywiki ti illumina la sfera.",
    ["Give it here, &lt;name&gt;."] = "Dallo qui, <name>.",
    ["Slay Arnak Grimtotem and bring proof of your deed to Cliffwatcher Longhorn in Freewind Post."] = "Uccidi Arnak Grimtotem e porta la prova della tua impresa a Cliffwatcher Longhorn a Freewind Post.",
    ["Reward from the quest 'Wanted!"] = "Ricompensa della missione 'Wanted!",
    ["Marez Cowl'."] = "Marez Cowl'.",
    ["Otto and Falconcrest'."] = "Otto and Falconcrest'.",
    ["&lt;name&gt;, I have crafted these weapons with the elunite you brought to me. &nbsp;Please, take whichever most suits you.And I must thank you. &nbsp;Working with elunite is both an honor and a pleasure."] = "<name>, ho forgiato queste armi con l'elunite che mi hai portato. Ti prego, prendi quella che più ti si addice.E devo ringraziarti. Lavorare con l'elunite è un onore e un piacere.",
    ["I have the whirlwind heart, and am ready to place it within your vessel of choice.Choose your weapon, &lt;name&gt;, and know that its power is the power of Cyclonian."] = "Ho il cuore del turbine e sono pronto a collocarlo nel recipiente che preferisci.Scegli la tua arma, <name>, e sappi che il suo potere è il potere di Cyclonian.",
    ["ProgressIt yearns to grow, &lt;name&gt;."] = "Brama di crescere, <name>.",
    ["The talisman has soaked in all that you have done."] = "Il talismano ha assorbito tutto ciò che hai fatto.",
    ["The thousands of troll corpses littering Zul'Gurub have fueled its power."] = "Le migliaia di cadaveri di troll che costellano Zul'Gurub ne hanno alimentato il potere.",
    ["Hand it to me and I shall make the final enhancement."] = "Consegnamelo e farò il potenziamento finale.",
    ["ProgressImpressive, &lt;name&gt;."] = "Impressionante, <name>.",
    ["You have a gift for killing that I have not sensed in another in many years."] = "Hai un talento per uccidere che non percepivo in nessun altro da molti anni.",
    ["Even Molthor is aware of the work that you have done for Zandalar."] = "Perfino Molthor è al corrente del lavoro che hai svolto per Zandalar.",
    ["It is time to enhance your talisman further."] = "È ora di potenziare ulteriormente il tuo talismano.",
    ["Give it to me."] = "Dammelo.",
    ["A Gnomeregan oddity whose Use effect grants a huge burst of attack speed."] = "Una stranezza di Gnomeregan il cui effetto Usa concede un enorme scatto di velocità d'attacco.",
    ["Feral druids kept it for that alone, because it works in cat form -- and it has limited charges, so every use is a decision."] = "I druidi ferini lo tenevano solo per quello, perché funziona in forma di gatto — e ha cariche limitate, quindi ogni utilizzo è una decisione.",
    ["A Nightmare-corrupted green dragon who splits himself into shades rather than face a fight whole."] = "Un drago verde corrotto dall'Incubo che si divide in ombre invece di affrontare il combattimento intero.",
    ["A blue dragon slain in Northrend and raised as a frost wyrm."] = "Un drago blu ucciso a Northrend e rialzato come viverna del gelo.",
    ["He guards the final approach to Kel'Thuzad's chamber."] = "Sorveglia l'ultimo accesso alla camera di Kel'Thuzad.",
    ["A bounty has been placed on the head of Marez Cowl, a high-level advisor and operative of the Syndicate."] = "È stata posta una taglia sulla testa di Marez Cowl, un consigliere di alto livello e agente del Syndicate.",
    ["She was last seen within the Syndicate controlled territory of Stromgarde."] = "È stata vista l'ultima volta nel territorio di Stromgarde controllato dal Syndicate.",
    ["A core hound of the deep fire, kept as a guard beast and fed by Ragnaros's lieutenants."] = "Un segugio del nucleo del fuoco profondo, tenuto come bestia da guardia e nutrito dai luogotenenti di Ragnaros.",
    ["A crafted helm that outlived several tiers of raid gear."] = "Un elmo creabile sopravvissuto a diversi livelli di equipaggiamento da incursione.",
    ["Its plans were the thing guilds actually fought over."] = "I suoi progetti erano ciò per cui le gilde litigavano davvero.",
    ["A crypt lord of Azjol-Nerub who took Arthas's side."] = "Un signore delle cripte di Azjol-Nerub che si schierò con Arthas.",
    ["He holds the Arachnid Quarter's outermost hall."] = "Tiene il salone più esterno del Quartiere degli Aracnidi.",
    ["A death knight who trains the Scourge's new officers."] = "Un cavaliere della morte che addestra i nuovi ufficiali della Piaga.",
    ["He is too strong for his own students to touch, which is exactly the point of the lesson."] = "È troppo forte perché i suoi stessi studenti possano toccarlo, ed è esattamente questo il senso della lezione.",
    ["A fungal horror grown in the Plague Quarter's spore vats -- less a creature than a crop that got out of hand."] = "Un orrore fungino cresciuto nelle vasche di spore del Quartiere della Peste — meno una creatura che un raccolto sfuggito di mano.",
    ["A giant spider webbed into the depths of the Arachnid Quarter, fed on whatever the Scourge no longer needs."] = "Un ragno gigante intrappolato nelle profondità del Quartiere degli Aracnidi, nutrito con ciò di cui la Piaga non ha più bisogno.",
    ["A green dragon of Ysera's flight, turned by the Nightmare and hunted across Feralas ever since."] = "Un drago verde del Volo di Ysera, corrotto dall'Incubo e braccato per Feralas da allora.",
    ["A hound handler of Ragnaros's court, who curses healing shut before the fighting starts."] = "Un addestratore di segugi della corte di Ragnaros, che maledice la guarigione impedendola prima che inizi il combattimento.",
    ["A human lord who traded his life for undeath and became a lich in Scholomance."] = "Un lord umano che scambiò la sua vita con la non morte e divenne un lich a Scholomance.",
    ["Killing him takes a blade specifically made to sever the bargain."] = "Per ucciderlo serve una lama fatta apposta per spezzare il patto.",
    ["A lieutenant of Ragnaros who fights surrounded by his Firesworn, and grows stronger each time one of them falls."] = "Un luogotenente di Ragnaros che combatte circondato dai suoi Firesworn e diventa più forte ogni volta che uno di loro cade.",
    ["A living mass of qiraji poison."] = "Una massa vivente di veleno qiraji.",
    ["It has to be frozen solid and then shattered, which is not how most things die."] = "Deve essere congelato completamente e poi frantumato, il che non è il modo in cui muore la maggior parte delle cose.",
    ["A necromancer of the Plague Quarter, promoted for his skill at raising what he had just finished killing."] = "Un negromante del Quartiere della Peste, promosso per la sua abilità nel rialzare ciò che aveva appena finito di uccidere.",
    ["A pit lord left behind when the Legion's invasion collapsed, still holding the Tainted Scar where the Dark Portal's blast burned the land."] = "Un signore della fossa rimasto indietro quando l'invasione della Legione è crollata, che ancora presidia la Tainted Scar dove l'esplosione del Portale Oscuro ha bruciato la terra.",
    ["A plain plate glove that became famous for its random enchants -- the of Strength roll is a 7.9% chance and was worth chasing over guaranteed epics for years."] = "Un semplice guanto di piastre diventato famoso per i suoi incantamenti casuali — la variante of Strength ha il 7,9% di probabilità e per anni è valsa la pena di inseguirla piuttosto che epici garantiti.",
    ["A princess of the earth elementals and the reason Maraudon is poisoned -- she holds the body of Zaetar, her demigod consort, at its heart."] = "Una principessa degli elementali della terra e la ragione per cui Maraudon è avvelenata — tiene il corpo di Zaetar, il suo consorte semidio, al suo centro.",
    ["A qiraji brood matron whose poison is potent enough that the fight is really a race against her venom."] = "Una matrona della covata qiraji il cui veleno è così potente che il combattimento è in realtà una corsa contro il suo veleno.",
    ["A red dragon of Alexstrasza's flight, broken by Nefarian's experiments."] = "Un drago rosso del Volo di Alexstrasza, spezzato dagli esperimenti di Nefarian.",
    ["He asks to be killed before the corruption finishes taking him, and apologises while he fights."] = "Chiede di essere ucciso prima che la corruzione finisca di prenderlo, e si scusa mentre combatte.",
    ["A sandworm grown enormous under the desert, surfacing only to feed."] = "Un verme delle sabbie diventato enorme sotto il deserto, che emerge solo per nutrirsi.",
    ["A stitched hound kept half-starved on purpose, so it would eat anything the Construct Quarter sent its way."] = "Un segugio cucito tenuto volutamente semi-affamato, così da mangiare qualsiasi cosa gli mandasse il Quartiere dei Costrutti.",
    ["A stone giant pressed into qiraji service, who drains the mana of everyone fighting him and turns to rock when full."] = "Un gigante di pietra costretto al servizio dei qiraji, che prosciuga il mana di chiunque lo combatta e si trasforma in roccia quando è sazio.",
    ["A vast qiraji burrower that spawns its young mid-fight and hurls intruders into the walls."] = "Un vasto scavatore qiraji che genera i suoi piccoli a metà combattimento e scaglia gli intrusi contro le pareti.",
    ["A worshipper of Kel'Thuzad who brought her followers with her into undeath, and still commands them."] = "Una devota di Kel'Thuzad che ha portato con sé i suoi seguaci nella non morte e li comanda ancora.",
    ["An Old God, buried under Ahn'Qiraj by the titans rather than killed."] = "Un Dio Antico, sepolto sotto Ahn'Qiraj dai titani anziché ucciso.",
    ["It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."] = "Da allora sussurra ai qiraji, e l'intera guerra esiste perché non ha mai smesso.",
    ["An abomination stitched together from the Scourge's leftovers, built for nothing but raw strength."] = "Un abominio cucito insieme con gli avanzi della Piaga, creato solo per la pura forza.",
    ["Archmage Arugal called the worgen to Silverpine to defend against the Scourge, lost control of them immediately, and went mad in Shadowfang Keep among the things he had summoned."] = "L'Arcimago Arugal chiamò i worgen a Silverpine per difendersi dalla Piaga, ne perse subito il controllo e impazzì a Shadowfang Keep tra le creature che aveva evocato.",
    ["Arugal's own belt."] = "La cintura di Arugal in persona.",
    ["He summoned the worgen to save Silverpine, then lost his mind in Shadowfang Keep surrounded by what he had called."] = "Evocò i worgen per salvare Silverpine, poi perse la ragione a Shadowfang Keep, circondato da ciò che aveva chiamato.",
    ["Avast Lubber!"] = "Ohé, marinaio d'acqua dolce!",
    ["Bring me 12 trinkets of the Arena Master and then ye shall be a Grandmaster of the Gurubashi Arena!"] = "Portami 12 gingilli dell'Arena Master e sarai un Gran Maestro dell'Arena dei Gurubashi!",
    ["C'Thun's mouthpiece."] = "Il portavoce di C'Thun.",
    ["Everything the qiraji believe, they believe because he told them the Old God said it."] = "Tutto ciò in cui credono i qiraji, lo credono perché lui ha detto loro che l'ha detto il Dio Antico.",
    ["Cut from the fang of one of Nefarian's drakes."] = "Ricavata dalla zanna di uno dei draghi di Nefarian.",
    ["Tanks wore it for the stun it shrugs off, not the numbers on it."] = "I tank la indossavano per lo stordimento che respinge, non per i numeri che ha.",
    ["Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five."] = "Il figlio di Deathwing, che lavora sotto Blackrock Mountain per allevare il volo cromatico — draghi con il sangue di tutti e cinque.",
    ["He spent years in Stormwind's court as Lord Victor Nefarius while the work went on."] = "Ha passato anni alla corte di Stormwind come Lord Victor Nefarius mentre il lavoro proseguiva.",
    ["Ghamoo-ra is the ancient turtle the naga keep in Blackfathom Deeps -- old enough that the Twilight cultists there treat it as part of the temple."] = "Ghamoo-ra è l'antica tartaruga che i naga tengono a Blackfathom Deeps — così vecchia che i cultisti del Twilight del posto la trattano come parte del tempio.",
    ["Hakkar's chief hexxer, who fights by binding pieces of his enemies' spirits and setting them loose."] = "Il capo stregone di Hakkar, che combatte legando pezzi dello spirito dei nemici e liberandoli.",
    ["He has overpowered all attempts at his capture."] = "Ha sopraffatto ogni tentativo di cattura.",
    ["The Stormwind Army has placed a generous bounty on the Gnoll."] = "L'Esercito di Stormwind ha posto una generosa taglia sul Gnoll.",
    ["Alas, you have proven yourself a brave and honorable soldier of the Frostwolf."] = "Ahimè, ti sei dimostrato un soldato coraggioso e onorevole dei Frostwolf.",
    ["Keeper of Naxxramas's plague works, and of the corridor of eruptions that has killed more raiders than he has."] = "Custode delle opere della peste di Naxxramas e del corridoio delle eruzioni che ha ucciso più incursori di quanti ne abbia uccisi lui.",
    ["Nefarian's best result: a two-headed chromatic horror carrying the breath of every dragonflight at once."] = "Il miglior risultato di Nefarian: un orrore cromatico a due teste che porta il soffio di ogni volo di draghi allo stesso tempo.",
    ["Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly."] = "Un tempo arcimago del Kirin Tor, lasciò Dalaran per fondare il Culto dei Dannati e servì Ner'zhul di buon grado.",
    ["Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."] = "Ucciso ad Andorhal e rialzato come lich, governa Naxxramas da un filatterio al suo centro.",
    ["One of Hakkar's high priests, who returns to his feet twice before he stays down."] = "Uno degli alti sacerdoti di Hakkar, che si rialza due volte prima di restare a terra.",
    ["One of Nefarian's three guardian drakes, holding the suspended walkways above the lair floor."] = "Uno dei tre draghi guardiani di Nefarian, che tiene le passerelle sospese sopra il pavimento della tana.",
    ["One of Ysera's four green consorts, corrupted by the Emerald Nightmare and now roaming Feralas, rotting the ground it stands on."] = "Una delle quattro consorti verdi di Ysera, corrotta dall'Emerald Nightmare e ora vaga per Feralas, facendo marcire il terreno su cui si trova.",
    ["One of the three qiraji councillors who fight as one -- kill any of them and the survivors grow stronger."] = "Uno dei tre consiglieri qiraji che combattono come uno solo — uccidine uno e i sopravvissuti diventano più forti.",
    ["One of three drakes guarding Nefarian's inner lair, and the one that heals itself off the wounds it deals."] = "Uno dei tre draghi che custodiscono la tana interna di Nefarian, quello che si cura con le ferite che infligge.",
    ["One of three weapons from the same solitary warrior trial."] = "Una di tre armi della stessa prova solitaria del guerriero.",
    ["Choosing it means giving up the axe and the staff for good."] = "Sceglierla significa rinunciare per sempre all'ascia e al bastone.",
    ["Ragnaros wielded this hammer as the Firelord."] = "Ragnaros impugnava questo martello come Signore del Fuoco.",
    ["Reforging it means taking the Eye of Sulfuras from Ragnaros himself and setting it into the Sulfuron Hammer."] = "Riforgiarlo significa prendere l'Eye of Sulfuras da Ragnaros in persona e incastonarlo nel Sulfuron Hammer.",
    ["Razuvious's colleague in the Military Quarter, who fights from behind his own dead and keeps sending them forward."] = "Il collega di Razuvious nel Quartiere Militare, che combatte da dietro i propri morti e continua a mandarli avanti.",
    ["Revelosh was a Shadowforge explorer who went into Uldaman looking for the origin of the dwarves, and became part of the ruin instead."] = "Revelosh era un esploratore dello Shadowforge che entrò a Uldaman in cerca dell'origine dei nani, e invece divenne parte della rovina.",
    ["Rise and be honored!"] = "Alzati e sii onorato!",
    ["Present your insignia."] = "Mostra la tua insegna.",
    ["Serra'kis is the great water beast the naga breed in the flooded halls of Blackfathom Deeps, and the reason the lower temple is under water at all."] = "Serra'kis è la grande bestia acquatica che i naga allevano nelle sale allagate di Blackfathom Deeps, ed è il motivo per cui il tempio inferiore è sott'acqua.",
    ["Son of Blackhand and the last warchief of the Dark Horde, still holding Blackrock Spire long after the rest of the Horde moved on."] = "Figlio di Blackhand e ultimo capoguerra dell'Orda Oscura, tiene ancora Blackrock Spire molto dopo che il resto dell'Orda è andato avanti.",
    ["Teebu's blade sets things on fire for reasons no one has ever explained."] = "La lama di Teebu dà fuoco alle cose per motivi che nessuno ha mai spiegato.",
    ["It is famous for being almost useless and deeply desirable at the same time."] = "È famosa per essere quasi inutile e profondamente desiderabile allo stesso tempo.",
    ["The Druids of the Fang broke from Cenarius and let the Emerald Nightmare into the Wailing Caverns."] = "I Druidi della Zanna si staccarono da Cenarius e lasciarono entrare l'Emerald Nightmare nelle Wailing Caverns.",
    ["These were theirs."] = "Questi erano i loro.",
    ["The Firelord, one of the four Elemental Lords, bound to the Elemental Plane until the Dark Iron dwarves summoned him under Blackrock Mountain."] = "Il Signore del Fuoco, uno dei quattro Lord Elementali, legato al Piano Elementale finché i nani Dark Iron non lo evocarono sotto Blackrock Mountain.",
    ["The summoning cracked the mountain open and made the Molten Core."] = "L'evocazione spaccò la montagna e creò il Molten Core.",
    ["The Guardian's staff, broken and scattered."] = "Il bastone del Guardiano, spezzato e disperso.",
    ["Rebuilding it means gathering forty splinters from Naxxramas, the base from Kel'Thuzad, and carrying it to the ruin of Karazhan where Medivh once held it."] = "Ricostruirlo significa raccogliere quaranta schegge da Naxxramas, la base da Kel'Thuzad, e portarlo alle rovine di Karazhan dove Medivh lo custodiva un tempo.",
    ["The Scarlet Crusade's chief scholar, who guards the Monastery library and its collection rather more aggressively than a librarian should."] = "Il capo studioso della Scarlet Crusade, che sorveglia la biblioteca del Monastero e la sua collezione in modo molto più aggressivo di quanto dovrebbe un bibliotecario.",
    ["The Soulflayer, a blood god the Atal'ai priests summoned into Zul'Gurub."] = "Il Soulflayer, un dio del sangue che i sacerdoti Atal'ai evocarono a Zul'Gurub.",
    ["He feeds on the blood of his own worshippers, which is the part they had not planned for."] = "Si nutre del sangue dei suoi stessi adoratori, cosa che non avevano previsto.",
    ["The Stromgarde Militia has placed bounties on the heads of Lord Falconcrest, and his bodyguard Otto."] = "La Milizia di Stromgarde ha posto taglie sulle teste di Lord Falconcrest e del suo guardaspalle Otto.",
    ["Falconcrest heads the Syndicate's efforts in the Arathi Highlands, and his death would cause a major disruption in those efforts."] = "Falconcrest guida gli sforzi del Syndicate negli Arathi Highlands, e la sua morte causerebbe un grave scompiglio in quegli sforzi.",
    ["The Whirlwind Axe comes from an elemental trial a warrior has to complete alone."] = "La Whirlwind Axe proviene da una prova elementale che un guerriero deve completare da solo.",
    ["Three weapons come from the same chain and you keep only one."] = "Tre armi provengono dalla stessa catena e ne tieni una sola.",
    ["The black dragonflight's overseer in Lower Blackrock Spire, keeping the orcs there in line on Nefarian's behalf."] = "Il sorvegliante del volo dei draghi neri nella Lower Blackrock Spire, che tiene in riga gli orchi per conto di Nefarian.",
    ["The blade the Silver Hand carried against the Scourge, and the one Tirion Fordring's order was built around."] = "La lama che la Silver Hand portò contro la Piaga, e quella attorno alla quale fu costruito l'ordine di Tirion Fordring.",
    ["Corrupted when Renault Mograine used it on his own father, Alexandros, in the Scarlet Monastery."] = "Corrotta quando Renault Mograine la usò contro suo padre Alexandros, nello Scarlet Monastery.",
    ["The last of Nefarian's three drakes, and the one that simply gets angrier as the fight goes on."] = "L'ultimo dei tre draghi di Nefarian, quello che semplicemente si arrabbia di più man mano che il combattimento prosegue.",
    ["The qiraji empire's finest soldier, who fights with her honour guard and refuses to be separated from them."] = "Il miglior soldato dell'impero qiraji, che combatte con la sua guardia d'onore e rifiuta di separarsene.",
    ["The third of the qiraji council, who charges the moment the fight begins and does not stop."] = "Il terzo del consiglio qiraji, che carica non appena inizia il combattimento e non si ferma.",
    ["Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength."] = "Imperatore gemello dei qiraji, quello che ha ereditato il dono della magia di C'Thun anziché la forza del fratello.",
    ["Neither twin can be killed far from the other."] = "Nessuno dei gemelli può essere ucciso lontano dall'altro.",
    ["Twin emperor of the qiraji, and the stronger arm of the pair."] = "Imperatore gemello dei qiraji, e il braccio più forte della coppia.",
    ["Two extra attacks on a proc, on a fast axe."] = "Due attacchi extra al proc, su un'ascia veloce.",
    ["Warriors farmed Dire Maul for this one item and nothing else."] = "I guerrieri facevano farming a Dire Maul solo per questo oggetto e nient'altro.",
    ["Wanted: Arnak Grimtotem Arnak the outcast is wanted for the heinous crimes of murder and kidnapping."] = "Wanted: Arnak Grimtotem Arnak l'emarginato è ricercato per i crimini efferati di omicidio e rapimento.",
    ["Handsome rewards will be given to those brave enough to bring this criminal to justice."] = "Generose ricompense saranno date a chi avrà il coraggio di consegnare questo criminale alla giustizia.",
    ["Wanted: Hogger A huge gnoll, Hogger, is prowling the woods in southwestern Elwynn."] = "Wanted: Hogger Un enorme gnoll, Hogger, si aggira nei boschi del sud-ovest di Elwynn.",
    ["Wanted: Maggot Eye!"] = "Wanted: Maggot Eye!",
    ["A foul beast, even by Gnoll standards, Maggot Eye has been sentenced to death for his crimes against The Forsaken."] = "Una bestia immonda, perfino per gli standard dei Gnoll, Maggot Eye è stato condannato a morte per i suoi crimini contro i Reietti.",
    ["This despicable villain has been stealing corpses for use by the Lich King's army."] = "Questo spregevole furfante ha rubato cadaveri per l'esercito del Re dei Lich.",
    ["We mages do more than just waggle our fingers and make pretty sparks!"] = "Noi maghi facciamo più che agitare le dita e fare belle scintille!",
    ["We control magic, the base fabric of our world!"] = "Controlliamo la magia, il tessuto di base del nostro mondo!",
    ["And that takes great care, and resolve."] = "E questo richiede grande cura e determinazione.",
    ["What is left of a green dragon who went into the Sunken Temple after the Nightmare and did not come out himself."] = "Ciò che resta di un drago verde che entrò nel Sunken Temple all'inseguimento dell'Incubo e non ne uscì sé stesso.",
    ["You have earned reverence among the Guard."] = "Hai guadagnato la reverenza tra la Guardia.",
    ["Present your insignia!"] = "Mostra la tua insegna!",
    ["You have earned the Eye of Command."] = "Hai guadagnato l'Eye of Command.",
    ["Present your insignia, Commander."] = "Mostra la tua insegna, Comandante.",
    ["For this, you have earned a rank of honor among the Stormpike."] = "Per questo hai guadagnato un grado d'onore tra gli Stormpike.",
    ["Your radiate command and power, shaman."] = "Irradi comando e potere, sciamano.",
    ["Exalted in the eyes of Frostwolf - the enemy cowers at the mention of your name."] = "Esaltato agli occhi dei Frostwolf — il nemico trema al solo sentire il tuo nome.",
    ["Your time has come again."] = "Il tuo momento è arrivato di nuovo.",
    ["You have earned a new ranking and as such, a new insignia denoting this rise in stature."] = "Hai guadagnato un nuovo grado e, di conseguenza, una nuova insegna che indica questa ascesa.",
    ["A burst of energy fills the caster, increasing his damage by 10 and armor by 150 for 15 sec."] = "Un'esplosione di energia riempie il lanciatore, aumentando i suoi danni di 10 e l'armatura di 150 per 15 sec.",
    ["Attack all nearby enemies, dealing weapon damage plus 5 every 3 sec for 9 sec, and reducing your own movement speed by 80%."] = "Attacca tutti i nemici vicini, infliggendo danni dell'arma più 5 ogni 3 sec per 9 sec, e riducendo la tua velocità di movimento dell'80%.",
    ["Blast the target with the fires of a forge, inflicting 51 Fire damage."] = "Colpisce il bersaglio con i fuochi di una forgia, infliggendo 51 danni da Fuoco.",
    ["Blasts enemies in front of you with the power of wind, fire, all that kind of thing!"] = "Colpisce i nemici davanti a te con il potere del vento, del fuoco, di tutta quella roba!",
    ["Blasts nearby enemies with thunder increasing the time between their attacks by 11% for 10 sec and doing 42 Nature damage to them. � Will affect up to 4 targets."] = "Colpisce i nemici vicini con il tuono, aumentando il tempo tra i loro attacchi dell'11% per 10 sec e infliggendo loro 42 danni da Natura. Colpisce fino a 4 bersagli.",
    ["Blunderflame the target for 1 to 111 Fire damage."] = "Blunderflame sul bersaglio per 1-111 danni da Fuoco.",
    ["Burns the enemy for 200 damage over 30 sec."] = "Brucia il nemico per 200 danni in 30 sec.",
    ["Burns the target for 33 Fire damage every 3 sec for 15 sec."] = "Brucia il bersaglio per 33 danni da Fuoco ogni 3 sec per 15 sec.",
    ["Concuss the target, slowing movement speed by 20% for 6 sec."] = "Stordisce il bersaglio con una botta, rallentando la velocità di movimento del 20% per 6 sec.",
    ["Cremate the target for 56 Fire damage."] = "Cremazione del bersaglio per 56 danni da Fuoco.",
    ["Damage caused by the target is reduced by 5 for 2 min."] = "I danni causati dal bersaglio sono ridotti di 5 per 2 min.",
    ["Deal 294 Physical damage and stun for1.5 sec."] = "Infligge 294 danni fisici e stordisce per 1,5 sec.",
    ["Trolls take 2 times as much damage and stun duration."] = "I troll subiscono il doppio dei danni e della durata dello stordimento.",
    ["Deal 84 Nature damage, increased by 2% per stack of Static Electricity."] = "Infligge 84 danni da Natura, aumentati del 2% per ogni accumulo di Static Electricity.",
    ["Deals 14 Nature damage every 3 sec to any enemy in an 8 yard radius around the caster for 12 sec."] = "Infligge 14 danni da Natura ogni 3 sec a ogni nemico in un raggio di 8 metri attorno al lanciatore per 12 sec.",
    ["Decrease the armor of the target by 100 for 20 sec. � While affected, the target cannot stealth or turn invisible."] = "Riduce l'armatura del bersaglio di 100 per 20 sec. Finché è colpito, il bersaglio non può usare furtività né diventare invisibile.",
    ["Deals 50% increased damage to targets below 25% health."] = "Infligge il 50% di danni in più ai bersagli sotto il 25% di salute.",
    ["Discipline the target, dealing 91 Physical damage."] = "Disciplina il bersaglio, infliggendo 91 danni fisici.",
    ["Canines and Hyenas are Stunned and sit for 3 sec."] = "Canidi e iene sono storditi e si siedono per 3 sec.",
    ["Diseases a target for 100 Nature damage and an additional 360 damage over 1 min."] = "Infetta un bersaglio per 100 danni da Natura e altri 360 danni in 1 min.",
    ["Disorients the target, causing it to wander aimlessly for up to 3 sec."] = "Disorienta il bersaglio, facendolo vagare senza meta fino a 3 sec.",
    ["Dispels a magic effect on the current foe."] = "Dissolve un effetto magico sul nemico attuale.",
    ["Enemy is inflicted with the Bleakwood Curse that reduces their magic resistances by 25. � Can be applied up to 3 times."] = "Il nemico viene colpito dalla Bleakwood Curse che riduce le sue resistenze magiche di 25. Può essere applicata fino a 3 volte.",
    ["Fires a Shadow Shot at the target for 21 to 31 Shadow damage."] = "Scaglia un Colpo d'Ombra contro il bersaglio per 21-31 danni da Ombra.",
    ["Heal yourself for 270 to 450 and increase your Strength by 120 for 30 sec."] = "Cura te stesso per 270-450 e aumenta la tua Forza di 120 per 30 sec.",
    ["Heals the wielder for 182 damage over 14 sec."] = "Cura chi lo impugna per 182 danni in 14 sec.",
    ["Hurl spikes at the target, dealing 45 Physical damage and jumping to 1 additional nearby enemy."] = "Scaglia spuntoni contro il bersaglio, infliggendo 45 danni fisici e passando a 1 ulteriore nemico vicino.",
    ["Each jump reduces the damage by 50%."] = "Ogni salto riduce i danni del 50%.",
    ["Ignite the target in the flames of the Great Forge, dealing 39 to 59 Holyfire damage."] = "Infiamma il bersaglio con le fiamme della Great Forge, infliggendo 39-59 danni da Fuocosacro.",
    ["Increases your chance to Parry attacks by 2% for 9 sec."] = "Aumenta del 2% la tua probabilità di parare gli attacchi per 9 sec.",
    ["Inflict 42 Fire and 14 Frost damage, slow the target by 50% for 5 sec, reduce armor by 50, and inflict 7 Nature damage every 3 sec for 12 sec."] = "Infligge 42 danni da Fuoco e 14 da Gelo, rallenta il bersaglio del 50% per 5 sec, riduce l'armatura di 50 e infligge 7 danni da Natura ogni 3 sec per 12 sec.",
    ["Knocks down all nearby enemies for 3 sec."] = "Atterra tutti i nemici vicini per 3 sec.",
    ["Launch a magic severing bolt at the target, dealing 36 Physical damage and interrupting the spell being cast for 5 sec."] = "Scaglia un dardo magico che recide il bersaglio, infliggendo 36 danni fisici e interrompendo l'incantesimo in corso per 5 sec.",
    ["Lowers the Attack Power of the target by 40 for 1 min."] = "Riduce la Potenza d'attacco del bersaglio di 40 per 1 min.",
    ["Protects the caster with a holy shield."] = "Protegge il lanciatore con uno scudo sacro.",
    ["Pummel the target for 25 damage and interrupt the spell being cast for 5 sec."] = "Colpisce il bersaglio per 25 danni e interrompe l'incantesimo in corso per 5 sec.",
    ["Punctures target's armor, lowering it by 100."] = "Perfora l'armatura del bersaglio, riducendola di 100.",
    ["Reduce your threat to the current target making them less likely to attack you."] = "Riduce la tua minaccia verso il bersaglio attuale, rendendo meno probabile che ti attacchi.",
    ["Reduces an enemy's armor by 165. � Stacks up to 3 times."] = "Riduce l'armatura di un nemico di 165. Si accumula fino a 3 volte.",
    ["Reduces targets armor by 300 for 20 sec."] = "Riduce l'armatura dei bersagli di 300 per 20 sec.",
    ["Sear certain enchanted targets with blazing light causing them to take additional damage from Holy attacks and spells."] = "Brucia certi bersagli incantati con luce abbagliante, facendogli subire danni aggiuntivi da attacchi e incantesimi Sacri.",
    ["Sear the target with a vortex of blazing wind, dealing 39 to 59 Holystorm damage."] = "Brucia il bersaglio con un vortice di vento ardente, infliggendo 39-59 danni da Tempestasacra.",
    ["Sear your target's flesh, dealing 67 to 101 Fire damage."] = "Brucia la carne del bersaglio, infliggendo 67-101 danni da Fuoco.",
    ["Slice the target's ankle, slowing movement speed by 30% for 6 sec."] = "Taglia la caviglia del bersaglio, rallentando la velocità di movimento del 30% per 6 sec.",
    ["Slices the enemy for 72 to 96 Nature damage."] = "Taglia il nemico per 72-96 danni da Natura.",
    ["Slows the target's movement by 50% for 10 sec."] = "Rallenta il movimento del bersaglio del 50% per 10 sec.",
    ["Slows the target's movement speed by 30% and increases the time between their attacks by 25% for 5 sec."] = "Rallenta la velocità di movimento del bersaglio del 30% e aumenta del 25% il tempo tra i suoi attacchi per 5 sec.",
    ["Smash the target for 85 damage."] = "Sfracella il bersaglio per 85 danni.",
    ["Smite your target with the power of the holy spring, inflicting 56 Holy damage."] = "Colpisci il bersaglio con il potere della sorgente sacra, infliggendo 56 danni Sacri.",
    ["Smites an enemy for 30 Holy damage."] = "Colpisce un nemico per 30 danni Sacri.",
    ["Spell damage taken by target increased by 15% for 5 sec."] = "I danni da incantesimo subiti dal bersaglio aumentano del 15% per 5 sec.",
    ["Strike the target with a Flaming Shell for 32 to 46 Fire damage."] = "Colpisci il bersaglio con un Flaming Shell per 32-46 danni da Fuoco.",
    ["Strike the target with a Flaming Shell, inflicting 7 Fire damage every 3 sec for 9 sec."] = "Colpisce il bersaglio con un Flaming Shell, infliggendo 7 danni da Fuoco ogni 3 sec per 9 sec.",
    ["Strike your target with Keeper's Sting for 23 to 33 Nature damage."] = "Colpisci il bersaglio con Keeper's Sting per 23-33 danni da Natura.",
    ["Tenderize the target, increasing physical damage taken by 1 for 1 min."] = "Rende tenero il bersaglio, aumentando di 1 i danni fisici subiti per 1 min.",
    ["Venom Shot the target for 23 to 33 Nature damage."] = "Venom Shot sul bersaglio per 23-33 danni da Natura.",
    ["Naga are Stunned for 2 sec."] = "I naga sono storditi per 2 sec.",
    ["Your attacks have a high chance to poison the target for 8 Nature damage every 3 sec for 9 sec."] = "I tuoi attacchi hanno un'alta probabilità di avvelenare il bersaglio per 8 danni da Natura ogni 3 sec per 9 sec.",
    ["Causes Wrath to have a 50% chance to restore 35 Mana."] = "Fa sì che Ira abbia il 50% di probabilità di ripristinare 35 mana.",
    ["Chance on harmful spell cast to reduce target's attack power by 60 for 30 sec."] = "Probabilità, lanciando un incantesimo dannoso, di ridurre la potenza d'attacco del bersaglio di 60 per 30 sec.",
    ["Chance on harmful spell cast to summon a Zombie Troll of Zum'rah for 20 sec."] = "Probabilità, lanciando un incantesimo dannoso, di evocare uno Zombie Troll of Zum'rah per 20 sec.",
    ["Chance on hit to blast the target for 25 to 31 Fire damage."] = "Probabilità al colpo di scagliare sul bersaglio un'esplosione di 25-31 danni da Fuoco.",
    ["Chance on hit to deal 69 to 81 Arcane damage."] = "Probabilità al colpo di infliggere 69-81 danni Arcani.",
    ["Chance on hit to grant nearby party members 4% increased critical strike chance."] = "Probabilità al colpo di concedere ai membri del gruppo vicini il 4% di probabilità di colpo critico in più.",
    ["Chance on hit to reduce the mana cost of your next spell cast within 10 sec by 24."] = "Probabilità al colpo di ridurre di 24 il costo in mana del prossimo incantesimo lanciato entro 10 sec.",
    ["Chance on hit to restore 32 mana."] = "Probabilità al colpo di ripristinare 32 mana.",
    ["Restores 3 times as much if attacking an Earth Elemental, Golem, or Titan-forged enemy."] = "Ripristina 3 volte tanto se si attacca un elementale della terra, un golem o un nemico forgiato dai Titani.",
    ["Chance to strike your ranged target with a Shadowbolt for 13 to 19 Shadow damage."] = "Probabilità di colpire il bersaglio a distanza con un Dardo d'Ombra per 13-19 danni da Ombra.",
    ["Harmful spell casts have a chance to steal 112 life from the target enemy over 8 sec."] = "Gli incantesimi dannosi hanno una probabilità di rubare 112 vita al nemico bersaglio in 8 sec.",
    ["Melee attacks deal 98 Fire additional damage against Frozen targets."] = "Gli attacchi in mischia infliggono 98 danni da Fuoco aggiuntivi ai bersagli Congelati.",
    ["Reduces all damage taken and chance to be critically hit by 5% in Warsong Gulch."] = "Riduce tutti i danni subiti e la probabilità di essere colpiti in modo critico del 5% in Warsong Gulch.",
    ["When damaged, has a chance to grant you 1080 armor for 12 sec."] = "Quando subisci danni, probabilità di ottenere 1080 armatura per 12 sec.",
    ["When damaged, has a chance to reduce threat level on all enemies by a small amount for 10 sec."] = "Quando subisci danni, probabilità di ridurre leggermente il livello di minaccia su tutti i nemici per 10 sec.",
    ["When struck in combat has a 3% chance to heal you for 60 to 100."] = "Quando vieni colpito in combattimento hai il 3% di probabilità di curarti per 60-100.",
    ["When struck in combat has a 5% chance to make you invulnerable to melee damage for 3 sec."] = "Quando vieni colpito in combattimento hai il 5% di probabilità di diventare invulnerabile ai danni in mischia per 3 sec.",
    ["This effect can only occur once every 10 sec."] = "Questo effetto può verificarsi solo una volta ogni 10 sec.",
    ["While in combat, your healing spells have a chance to grant an ally 300 armor for 10 sec."] = "In combattimento, i tuoi incantesimi di guarigione hanno una probabilità di concedere a un alleato 300 armatura per 10 sec.",
    ["Your Frostbolt spells have a 6% chance to restore 50 mana when cast."] = "I tuoi incantesimi Dardo di Gelo hanno il 6% di probabilità di ripristinare 50 mana al lancio.",
    ["Your Lacerate hits have a 10% chance to reset the cooldown on Mangle (Bear)."] = "I tuoi colpi di Lacerate hanno il 10% di probabilità di azzerare il tempo di recupero di Mangle (Orso).",
    ["Your healing spells have a 5% chance to remove 1 Poison effect from the target."] = "I tuoi incantesimi di guarigione hanno il 5% di probabilità di rimuovere 1 effetto di Veleno dal bersaglio.",
    ["Absorbs 600 magical damage. � Lasts 2 min."] = "Assorbe 600 danni magici. Dura 2 min.",
    ["Allows you to look far into the distance."] = "Ti permette di guardare lontano.",
    ["Attach a lure to your equipped fishing pole, increasing Fishing by 25 for 10 min."] = "Applica un'esca alla canna da pesca equipaggiata, aumentando Pesca di 25 per 10 min.",
    ["Attempts to cure 1 poison effect on the target, and 1 more poison effect every 2 seconds for 8 sec."] = "Tenta di curare 1 effetto di veleno sul bersaglio e 1 altro effetto di veleno ogni 2 secondi per 8 sec.",
    ["Balance the Powers of the Moon, Emerald Dream, and Wild to learn a new ability."] = "Equilibra i Poteri della Luna, del Sogno di Smeraldo e della Natura per imparare una nuova abilità.",
    ["Channels a bolt of lightning and hurls it towards all enemies in front of the caster causing 189 to 209 Nature damage."] = "Incanala un fulmine e lo scaglia contro tutti i nemici davanti al lanciatore causando 189-209 danni da Natura.",
    ["The caster is then surrounded by a barrier of electricit"] = "Il lanciatore è poi circondato da una barriera di elettricità.",
    ["Chop nearby Humanoid or Undead corpse in two, restoring 150 Health, 150 Mana, and 15 Rage."] = "Taglia in due un cadavere umanoide o non morto vicino, ripristinando 150 salute, 150 mana e 15 rabbia.",
    ["Combines Jang'thraze and Sang'thraze to form the mighty sword, Sul'thraze."] = "Combina Jang'thraze e Sang'thraze per formare la possente spada Sul'thraze.",
    ["Conjures food to eat."] = "Evoca cibo da mangiare.",
    ["Creates a portal, teleporting group members that use it to Karazhan."] = "Crea un portale che teletrasporta a Karazhan i membri del gruppo che lo usano.",
    ["Deal 607 Physical damage split between up to 4 nearby enemies."] = "Infligge 607 danni fisici suddivisi fra fino a 4 nemici vicini.",
    ["Deals 25 Fire damage every 5 sec to all nearby enemies for 15 sec."] = "Infligge 25 danni da Fuoco ogni 5 sec a tutti i nemici vicini per 15 sec.",
    ["Deals 504 Fire damage over 12 sec."] = "Infligge 504 danni da Fuoco in 12 sec.",
    ["Demons and Beasts are Rooted in place for 6 sec."] = "Demoni e bestie sono bloccati sul posto per 6 sec.",
    ["Deals 75 Fire damage every 1 sec for 5 sec to all enemies in front of you."] = "Infligge 75 danni da Fuoco ogni 1 sec per 5 sec a tutti i nemici davanti a te.",
    ["Gets you quite drunk too!"] = "Ti ubriaca parecchio!",
    ["Decrease the armor of target by 50 for 1 min."] = "Riduce l'armatura del bersaglio di 50 per 1 min.",
    ["Dig up a grave."] = "Dissotterra una tomba.",
    ["Usable at Raven Hill Cemetery and Scarlet Monastery Graveyard."] = "Utilizzabile al Raven Hill Cemetery e al cimitero dello Scarlet Monastery.",
    ["Escape all immobilizing effects."] = "Sfugge a tutti gli effetti di immobilizzazione.",
    ["Fear all Demons within 15 yds for 6 sec."] = "Terrorizza tutti i Demoni entro 15 metri per 6 sec.",
    ["Gain the ability to walk on water for 5 min.Attacking or taking damage will cancel this effect."] = "Ottieni la capacità di camminare sull'acqua per 5 min.Attaccare o subire danni annulla questo effetto.",
    ["Heal your pet for 450 to 750."] = "Cura il tuo animale per 450-750.",
    ["Increase Rage by 30."] = "Aumenta la rabbia di 30.",
    ["Increase experience gained from slaying Undead by 10% for 5 min."] = "Aumenta l'esperienza ottenuta uccidendo Non Morti del 10% per 5 min.",
    ["Increase your run speed by 60% for 10 sec, but deals 100 to 500 damage and drains 100 to 500 mana every 2 seconds."] = "Aumenta la tua velocità di corsa del 60% per 10 sec, ma infligge 100-500 danni e prosciuga 100-500 mana ogni 2 secondi.",
    ["This effect is doubled in Volcanic areas."] = "Questo effetto è raddoppiato nelle aree vulcaniche.",
    ["Increases Fire resistance by 33 and absorbs 465 Fire damage. � Lasts 15 sec."] = "Aumenta la resistenza al Fuoco di 33 e assorbe 465 danni da Fuoco. Dura 15 sec.",
    ["Increases all Resistances by 10 and grants Immunity to Fear for 30 sec."] = "Aumenta tutte le Resistenze di 10 e concede Immunità alla Paura per 30 sec.",
    ["Increases damage and healing done by magical spells and effects by up to 130 for 20 sec."] = "Aumenta i danni e la guarigione inflitti dagli incantesimi ed effetti magici fino a 130 per 20 sec.",
    ["Increases healing done by the next 5 spells by up to 450 for 30 sec."] = "Aumenta la guarigione dei prossimi 5 incantesimi fino a 450 per 30 sec.",
    ["Increases your Block chance by 8% for 15 sec."] = "Aumenta dell'8% la tua probabilità di Bloccare per 15 sec.",
    ["This effect is doubled in Strongholds and Cities."] = "Questo effetto è raddoppiato nelle Roccaforti e nelle Città.",
    ["Increases your attack speed by 50% for 30 sec."] = "Aumenta la tua velocità d'attacco del 50% per 30 sec.",
    ["Increases your chance to Dodge by 3% for 20 sec."] = "Aumenta del 3% la tua probabilità di Schivare per 20 sec.",
    ["Increases your critical strike chance with all spells and attacks by 5% for 20 sec or until you deal a non-periodic critical effect."] = "Aumenta del 5% la tua probabilità di colpo critico con tutti gli incantesimi e gli attacchi per 20 sec o finché non infliggi un effetto critico non periodico.",
    ["Increases your effective stealth detection level by 3 for 10 sec, then reduces your effective stealth detection level by 6 for 20 sec."] = "Aumenta di 3 il tuo livello effettivo di rilevamento della furtività per 10 sec, poi lo riduce di 6 per 20 sec.",
    ["Increases your melee and ranged attack power by 280. � Effect lasts for 20 sec."] = "Aumenta la tua potenza d'attacco in mischia e a distanza di 280. L'effetto dura 20 sec.",
    ["Lets you walk on water for 1 min."] = "Ti permette di camminare sull'acqua per 1 min.",
    ["Marks a target for delivery."] = "Contrassegna un bersaglio per la consegna.",
    ["After landing 6 to 8 spells or attacks, deal 467 Fire damage."] = "Dopo aver messo a segno da 6 a 8 incantesimi o attacchi, infligge 467 danni da Fuoco.",
    ["Number of spells or attacks is halved in Snowy areas."] = "Il numero di incantesimi o attacchi è dimezzato nelle aree innevate.",
    ["Melee attacks deal an additional 7 Fire damage for 30 sec."] = "Gli attacchi in mischia infliggono 7 danni da Fuoco aggiuntivi per 30 sec.",
    ["Page Everlook Emergency Services for a Parachute-Priest that will assist in healing allies for 15 sec."] = "Chiama gli Everlook Emergency Services per un Parachute-Priest che aiuterà a curare gli alleati per 15 sec.",
    ["Perform a Propellerstorm, reducing your fall speed for 15 sec and dealing 100% weapon damage to nearby enemies when you land."] = "Esegue una Propellerstorm, riducendo la tua velocità di caduta per 15 sec e infliggendo il 100% dei danni dell'arma ai nemici vicini quando atterri.",
    ["Purifies the friendly target, removing 1 disease effect and 1 poison effect."] = "Purifica il bersaglio amico, rimuovendo 1 effetto di malattia e 1 effetto di veleno.",
    ["Raise the severed head of Roogug, Horrifying and Silencing all Swine within 15 yds for 5 sec."] = "Solleva la testa mozzata di Roogug, Terrorizzando e Silenziando tutti i Maiali entro 15 metri per 5 sec.",
    ["Reduces your fall speed for 10 sec."] = "Riduce la tua velocità di caduta per 10 sec.",
    ["Removes existing Immobilizing effects and makes you immune to Immobilizing effects for 5 sec."] = "Rimuove gli effetti di immobilizzazione esistenti e ti rende immune agli effetti di immobilizzazione per 5 sec.",
    ["Restores 1293 mana over 27 sec. � Must remain seated while drinking."] = "Ripristina 1293 mana in 27 sec. Devi restare seduto mentre bevi.",
    ["Can only be used at 10% health."] = "Utilizzabile solo al 10% di salute.",
    ["Slice open and gather from a target Copper, Tin, Silver, or Iron Vein (does not require Mining)."] = "Taglia e raccogli da una vena di rame, stagno, argento o ferro (non richiede Estrazione).",
    ["Slows nearby enemies by 50% for 10 sec, increased to 80% in Desert areas."] = "Rallenta i nemici vicini del 50% per 10 sec, aumentato all'80% nelle aree desertiche.",
    ["Stuns target Undead for 6 sec."] = "Stordisce un Non Morto bersaglio per 6 sec.",
    ["Stuns target Worgen for 4 sec."] = "Stordisce un Worgen bersaglio per 4 sec.",
    ["Summons a tracking hound that will protect you for 3 min."] = "Evoca un segugio da tracciamento che ti proteggerà per 3 min.",
    ["Weakens the servants of Razelikh the Defiler."] = "Indebolisce i servitori di Razelikh the Defiler.",
    ["Must be within close proximity of the target to activate."] = "Devi essere molto vicino al bersaglio per attivarlo.",
    ["As my understanding of Arugal's magic grows so does my disdain for the hapless fool."] = "Man mano che comprendo meglio la magia di Arugal, cresce il mio disprezzo per quello sciocco.",
    ["I am close to completing my research on his so called remedy."] = "Sono vicino a completare la mia ricerca sul suo cosiddetto rimedio.",
    ["Edwin VanCleef must be assassinated."] = "Edwin VanCleef deve essere assassinato.",
    ["While it saddens me to condemn any man to a death sentence, it is for the greater good of the people of Westfall that VanCleef is laid to rest once and for all."] = "Pur rattristandomi condannare qualcuno a una sentenza di morte, è per il bene superiore della gente di Westfall che VanCleef venga messo a riposo una volta per tutte.",
    ["Here is the final challenge that I will put forth."] = "Ecco l'ultima sfida che ti proporrò.",
    ["We've been tracking an elusive tiger for weeks."] = "Stiamo seguendo da settimane una tigre elusiva.",
    ["I draw my power - my will to continue living and breathing - from the unmitigated hatred I have for the Scourge and all that they have done."] = "Traggo il mio potere — la mia volontà di continuare a vivere e respirare — dall'odio incontrollato che provo per la Piaga e per tutto ciò che ha fatto.",
    ["I must warn you, this matter must stay between us."] = "Devo avvertirti, questa faccenda deve restare tra noi.",
    ["The satyr are enough of an embarrassment to us already, and this one is much too close to home."] = "I satiri sono già abbastanza un imbarazzo per noi, e questo è troppo vicino a casa.",
    ["Prospector Whelgar now holds the original fossil at his site in the Wetlands."] = "Prospector Whelgar ora tiene il fossile originale nel suo sito nelle Wetlands.",
    ["When I discovered the Stone of Relu, I believed it to be the key to unlocking the mystery of the fossil."] = "Quando scoprii la Stone of Relu, credetti fosse la chiave per svelare il mistero del fossile.",
    ["So the prospector wants to send the mysterious fossil to the Explorers' League in Darnassus?"] = "Quindi il prospettore vuole mandare il misterioso fossile all'Explorers' League a Darnassus?",
    ["I don't feel right leaving Darkshore without him."] = "Non mi sento a mio agio a lasciare Darkshore senza di lui.",
    ["Strength has left me."] = "La forza mi ha abbandonato.",
    ["Your help is needed!"] = "Serve il tuo aiuto!",
    ["Long ago this site was a great temple of Elune."] = "Molto tempo fa questo luogo era un grande tempio di Elune.",
    ["But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well."] = "Ma la sfortuna portò alla rovina quando la corruzione di un Dio Antico risalì da sotto la terra e contaminò il sacro Pozzo Lunare.",
    ["This Twilight's Hammer follower cannot be allowed to complete his plan."] = "Questo seguace del Twilight's Hammer non deve poter completare il suo piano.",
    ["The Twilight's Hammer do not understand the spirits of nature."] = "Il Twilight's Hammer non comprende gli spiriti della natura.",
    ["They believe in the Old Gods--creatures of chaos and destruction that were long ago defeated."] = "Credono negli Dei Antichi — creature di caos e distruzione sconfitte molto tempo fa.",
    ["This shard holds great secrets; it is the pure essence of the Emerald Dream."] = "Questa scheggia custodisce grandi segreti; è la pura essenza del Sogno di Smeraldo.",
    ["However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare."] = "Tuttavia, ciò che vedo in questa scheggia non è un sogno; lo si potrebbe chiamare una visione, una specie di incubo.",
    ["We believe they are hiding out in the Dagger Hills, plotting their next move."] = "Crediamo che si nascondano nei Dagger Hills, a progettare la loro prossima mossa.",
    ["Slay the wretches in the name of The People's Militia."] = "Uccidi i miserabili in nome della People's Militia.",
    ["While I traveled on the road to meet Whelgar, I was attacked by raptors and the relic was lost."] = "Mentre viaggiavo sulla strada per incontrare Whelgar, sono stato attaccato dai raptor e la reliquia è andata persa.",
    ["(be aware that some vendors sell items at random)"] = "(tieni presente che alcuni venditori vendono oggetti in modo casuale)",
    ["Bought from Rune Broker in Stormwind, Ironforge, Darnassus, Elwynn Forest, Dun Morogh, and Teldrassil."] = "Comprato da Rune Broker a Stormwind, Ironforge, Darnassus, Elwynn Forest, Dun Morogh e Teldrassil.",
    ["Bought from Rune Broker in Orgrimmar, Thunder Bluff, Undercity, Durotar, Mulgore, and Tirisfal Glades."] = "Comprato da Rune Broker a Orgrimmar, Thunder Bluff, Undercity, Durotar, Mulgore e Tirisfal Glades.",
    ["Bought from Rune Broker in Stormwind, Ironforge, Darnassus, Elwynn Forest, Dun Morogh, and Teldrassil, and in Orgrimmar, Thunder Bluff, Undercity, Durotar, Mulgore, and Tirisfal Glades."] = "Comprato da Rune Broker a Stormwind, Ironforge, Darnassus, Elwynn Forest, Dun Morogh e Teldrassil, e a Orgrimmar, Thunder Bluff, Undercity, Durotar, Mulgore e Tirisfal Glades.",
    ["Found in a container."] = "Si trova in un contenitore.",
    ["The belt is crafted afterwards."] = "La cintura si crea dopo.",
    ["You have 5 hours to complete this task."] = "Hai 5 ore per completare questo compito.",
    ["Collect 4 pieces for the heal and mana, and all 5 for Dream Venom."] = "Raccogli 4 pezzi per la cura e il mana, e tutti e 5 per Dream Venom.",
    ["Collect 4 pieces for the heal and mana."] = "Raccogli 4 pezzi per la cura e il mana.",
    ["Provided item:."] = "Oggetto fornito:",
    ["The Blacksmithing plans are a drop."] = "I progetti di Forgiatura sono un bottino.",
    ["The creature is not named yet."] = "La creatura non ha ancora un nome.",
}) do sentences[k] = v end
